window.BANQUE_INFINI = {"module":"annee-2/pratique/semestre-1/cardio-respi","titre":"Cardio-respiratoire","sources":[{"t":"Aspiration des sécrétions chez l'adulte","q":"aspiration/quiz.html","f":"aspiration/fiche.html"},{"t":"Auscultation pulmonaire","q":"auscultation-pulmonaire/quiz.html","f":"auscultation-pulmonaire/fiche.html"},{"t":"Contrôle respiratoire et facilitation diaphragmatique","q":"controle-respiratoire/quiz.html","f":"controle-respiratoire/fiche.html"},{"t":"Désobstruction bronchique et stratégies instrumentales","q":"desobstruction-bronchique/quiz.html","f":"desobstruction-bronchique/fiche.html"},{"t":"Épreuve fonctionnelle respiratoire et ECG","q":"efr-et-ecg-pratique/quiz.html","f":"efr-et-ecg-pratique/fiche.html"},{"t":"Examen objectif — inspection et palpation","q":"examen-objectif/quiz.html","f":"examen-objectif/fiche.html"},{"t":"Kinésithérapie respiratoire en pédiatrie","q":"kine-respiratoire-pediatrie/quiz.html","f":"kine-respiratoire-pediatrie/fiche.html"},{"t":"Évaluation et entraînement des muscles respiratoires","q":"muscles-respiratoires/quiz.html","f":"muscles-respiratoires/fiche.html"},{"t":"Positionnement et mobilisation thoracique","q":"positionnement-mobilisation-thoracique/quiz.html","f":"positionnement-mobilisation-thoracique/fiche.html"}],"questions":[{"q":"Comment définit-on l'aspiration des voies aériennes ?","o":["Le retrait des sécrétions par un cathéter sous pression négative","L'insufflation d'air sous pression positive par une sonde nasale","La nébulisation de sérum physiologique dans la trachée","La percussion manuelle du thorax pour décoller le mucus"],"r":0,"e":"Elle vise à favoriser la clairance, maintenir la perméabilité, améliorer l'oxygénation et prévenir les atélectasies.","s":0},{"q":"Quel signe sur la courbe de débit de la ventilation mécanique indique une aspiration ?","o":["Un aspect en « dents de scie »","Un plateau prolongé","Une courbe plate","Une double bosse inspiratoire"],"r":0,"e":"Les autres indications incluent l'hypoxémie, l'effort respiratoire élevé et les sécrétions visibles.","s":0},{"q":"Que faut-il privilégier avant de recourir à l'aspiration ?","o":["Encourager une clairance par des techniques moins invasives","Augmenter d'emblée la FiO₂ pour prévenir la désaturation","Instiller du sérum pour fluidifier d'abord les sécrétions","Passer en système fermé pour limiter la contamination"],"r":0,"e":"L'aspiration reste une technique invasive.","s":0},{"q":"La pression intracrânienne élevée est-elle une contre-indication à l'aspiration ?","o":["Oui, c'est une contre-indication","Non, c'est une indication","Oui, mais uniquement chez l'enfant","Non, sauf en ventilation mécanique"],"r":0,"e":"On retient aussi l'hémorragie nasale, la chirurgie trachéale, l'instabilité cardiaque et le bronchospasme sévère.","s":0},{"q":"Quelle est une contre-indication de l'aspiration liée au trajet de la sonde ?","o":["Une altération anatomique sur le trajet de la sonde","Une hypersécrétion abondante dans les voies aériennes","Une toux inefficace malgré les techniques manuelles","Une atélectasie visible à la radiographie du thorax"],"r":0,"e":"Les altérations hémodynamiques majeures en sont une autre.","s":0},{"q":"Quelle est une caractéristique du système ouvert ?","o":["Il se fait à l'air ambiant, avec déconnexion de la sonde","Il se fait sans déconnexion, sur le circuit du ventilateur","Il coûte plus cher, car la sonde reste en place","Il aspire un volume moindre, grâce au circuit clos"],"r":0,"e":"Le système fermé est généralement utilisé en ventilation mécanique.","s":0},{"q":"Quel système aspire un volume plus important ?","o":["Le système ouvert","Le système fermé","Les deux également","Cela ne dépend pas du système"],"r":0,"e":"Le système ouvert est aussi moins coûteux mais impose une déconnexion.","s":0},{"q":"Quel système est généralement utilisé en ventilation mécanique ?","o":["Le système fermé","Le système ouvert","Indifféremment l'un ou l'autre","Aucun des deux"],"r":0,"e":"Il évite la déconnexion de la sonde, mais son coût est plus élevé.","s":0},{"q":"Quelle quantité de sérum physiologique peut-on instiller ?","o":["2 mL, toujours moins de 10 mL","20 mL, toujours moins de 30 mL","50 mL, toujours moins de 100 mL","10 mL, toujours moins de 20 mL"],"r":0,"e":"Il faut peser les effets indésirables possibles.","s":0},{"q":"Quel effet indésirable l'instillation de sérum peut-elle provoquer ?","o":["Une baisse de la saturation en oxygène","Une hausse de la saturation en oxygène","Une baisse de la pression intracrânienne","Une bronchodilatation réflexe immédiate"],"r":0,"e":"On retient aussi la toux excessive, le bronchospasme, la tachycardie et l'augmentation de la PIC.","s":0},{"q":"Combien de temps faut-il pré-oxygéner avant l'aspiration ?","o":["1 minute à 100 %","5 minutes à 50 %","10 secondes à 100 %","Il ne faut jamais pré-oxygéner"],"r":0,"e":"Attention : en cas de pression intracrânienne élevée, il ne faut pas pré-oxygéner.","s":0},{"q":"Dans quel cas ne faut-il PAS pré-oxygéner ?","o":["En cas de pression intracrânienne élevée","En cas d'hypoxémie avant l'aspiration","En cas de sécrétions très abondantes","En cas de ventilation mécanique invasive"],"r":0,"e":"C'est une précaution spécifique du cours.","s":0},{"q":"Quelle est la pression de vide actuellement recommandée chez l'adulte ?","o":["−80 mmHg","−100 à −150 mmHg","−200 mmHg","−250 mmHg"],"r":0,"e":"La recommandation antérieure était de −100 à −150 mmHg ; le maximum est de −200 mmHg.","s":0},{"q":"Quelle est la pression de vide maximale admise chez l'adulte ?","o":["−200 mmHg","−80 mmHg","−150 mmHg","−300 mmHg"],"r":0,"e":"La valeur actuellement recommandée est de −80 mmHg.","s":0},{"q":"Quelle est la durée maximale d'application continue du vide ?","o":["15 secondes","30 secondes","5 secondes","1 minute"],"r":0,"e":"Cette durée est la même que celle de la manœuvre complète d'aspiration.","s":0},{"q":"Quelle règle s'applique au diamètre du cathéter d'aspiration ?","o":["Il n'occlut pas plus de 50 % de la lumière","Il occlut au moins 80 % de la lumière","Il occlut toute la lumière pour aspirer plus","Il est choisi sans règle, selon le stock"],"r":0,"e":"La sonde peut comporter un ou plusieurs orifices et des valves de contrôle.","s":0},{"q":"Quel type de lubrifiant utilise-t-on pour l'abord nasopharyngé ?","o":["Un lubrifiant anesthésique à base d'eau","Un lubrifiant huileux à base de paraffine","De la vaseline appliquée sur toute la sonde","Aucun, la sonde est déjà prélubrifiée"],"r":0,"e":"Il fait partie du matériel à préparer avec le raisonnement clinique.","s":0},{"q":"Quel équipement de protection individuelle est requis ?","o":["Blouse, masque, lunettes et gants","Gants seuls, stériles ou non stériles","Masque et gants, sans les lunettes","Blouse et gants, sans le masque"],"r":0,"e":"Le choix entre gants stériles et non stériles dépend de la politique locale.","s":0},{"q":"Quelle main gante-t-on en premier ?","o":["La main dominante","La main non dominante","Indifféremment","Les deux simultanément"],"r":0,"e":"On saisit le bord du poignet avec les 3 premiers doigts de la main non dominante, en ne touchant que la surface interne.","s":0},{"q":"Lors de l'enfilage du second gant, quelle surface touche-t-on ?","o":["La surface externe, en glissant les doigts sous le poignet","La surface interne, en saisissant le bord retourné","Les deux surfaces, en tirant fermement sur le bord du poignet","Le bord libre, en pinçant le gant entre deux doigts"],"r":0,"e":"Il ne faut jamais toucher une surface stérile avec une surface non stérile.","s":0},{"q":"Dans quel sens retire-t-on le premier gant ?","o":["De la paume vers les doigts, sans que l'extérieur touche la peau","Des doigts vers la paume, en tirant sur chaque doigt un à un","En le déchirant au niveau du poignet pour aller plus vite","En le secouant pour le faire glisser hors des doigts"],"r":0,"e":"Le gant retiré est tenu dans la paume de la main droite.","s":0},{"q":"Quels doigts utilise-t-on pour retirer le second gant ?","o":["Les 2ᵉ et 3ᵉ doigts, par l'intérieur non contaminé","Le pouce et l'index, par l'extérieur du gant","Les 4ᵉ et 5ᵉ doigts, par le bord du poignet","Toute la main, en saisissant la paume du gant"],"r":0,"e":"Le mouvement doit être ferme, sans déchirer le gant.","s":0},{"q":"Quels patients bénéficient de l'abord oropharyngé ?","o":["AVC, sialorrhée, gériatrie et troubles de déglutition","Patients intubés, sédatés et sous ventilation invasive","Trachéotomisés, en sevrage ventilatoire, à canule fixe","BPCO stable, asthme contrôlé et toux efficace"],"r":0,"e":"On utilise la canule de Yankauer ; attention au réflexe de déglutition.","s":0},{"q":"Quel dispositif utilise-t-on pour l'aspiration oropharyngée ?","o":["La canule de Yankauer","Le Flutter VRP1","Le spiromètre incitatif","Le Threshold IMT"],"r":0,"e":"Cet abord bénéficie notamment aux patients avec troubles de la déglutition.","s":0},{"q":"Comment introduit-on la sonde d'aspiration ?","o":["En ligne droite descendante, sans appliquer le vide","En spirale descendante, en appliquant le vide","En ligne droite, en appliquant le vide dès l'entrée","Par va-et-vient rapides, en vide intermittent"],"r":0,"e":"L'entrée se fait en induisant une flexion à l'extrémité de la sonde.","s":0},{"q":"Que fait-on lorsqu'on sent une résistance ?","o":["S'arrêter, remonter de 1 cm, puis appliquer le vide","Forcer légèrement le passage, puis appliquer le vide","Appliquer le vide tout de suite, sans remonter","Remonter de 5 cm, puis réintroduire la sonde"],"r":0,"e":"La résistance correspond à la carène ou à un bouchon de sécrétions.","s":0},{"q":"Comment retire-t-on la sonde ?","o":["En spirale ascendante, le vide appliqué avec le pouce","En ligne droite ascendante, sans appliquer aucun vide","Par à-coups successifs, en vide continu","Lentement, en ligne droite, la sonde clampée"],"r":0,"e":"La durée totale doit rester inférieure ou égale à 15 secondes.","s":0},{"q":"Quelle complication cardiaque l'aspiration peut-elle provoquer ?","o":["Des arythmies et une hausse de la fréquence cardiaque","Un bloc auriculo-ventriculaire complet systématique","Une baisse de la pression artérielle systolique","Une baisse de la fréquence cardiaque, sans arythmie"],"r":0,"e":"On observe aussi une augmentation de la pression artérielle systolique, moyenne, de perfusion cérébrale et intracrânienne.","s":0},{"q":"Quelle complication locale l'aspiration peut-elle entraîner ?","o":["Trauma muqueux, trachéite, lacération ou perforation","Brûlure cutanée, eczéma ou réaction allergique locale","Fracture costale, contusion ou hématome du thorax","Luxation mandibulaire, entorse cervicale ou torticolis"],"r":0,"e":"La désaturation en oxygène et l'anxiété font aussi partie des complications.","s":0},{"q":"Que doit-on faire pendant toute la durée de l'aspiration ?","o":["Surveiller le patient tout au long du geste","Interrompre le monitorage pour éviter les alarmes","Débrancher l'oxygène le temps du passage de la sonde","Demander au patient de retenir sa respiration"],"r":0,"e":"La surveillance est la 6ᵉ étape de la technique.","s":0},{"q":"Quelles indications d'aspiration relèvent d'une incapacité à éliminer les sécrétions ?","o":["Sécrétions audibles ou visibles","Réflexe de toux altéré","Conscience altérée par une atteinte neurologique","Hypoxémie avec une saturation qui chute"],"r":[0,1,2],"e":"L'incapacité à éliminer les sécrétions regroupe ces trois situations. L'hypoxémie et l'effort respiratoire élevé constituent des indications distinctes.","s":0},{"q":"Quels signes auscultatoires indiquent une aspiration ?","o":["Bruits respiratoires diminués","Râles au-dessus de la trachée","Frémissement","Murmure vésiculaire normal"],"r":[0,1,2],"e":"Bruits diminués et bruits adventices — râles trachéaux, frémissement — figurent parmi les indications.","s":0},{"q":"Quelles contre-indications de l'aspiration sont citées dans ce cours pratique ?","o":["Altérations structurelles anatomiques sur le trajet de la sonde","Hémorragie nasale et chirurgie de la trachée","Instabilité cardiaque et bronchospasme sévère","Pression intracrânienne élevée","Sécrétions visibles dans la sonde endotrachéale"],"r":[0,1,2,3],"e":"Ces contre-indications s'ajoutent aux altérations hémodynamiques majeures.","s":0},{"q":"Quelles caractéristiques distinguent le système fermé ?","o":["Pas de déconnexion de la sonde","Volume aspiré moindre","Coût plus élevé","Aspiration à l'air ambiant"],"r":[0,1,2],"e":"Le système fermé évite la déconnexion, aspire un volume moindre et coûte plus cher. Le système ouvert aspire à l'air ambiant, avec déconnexion, un volume plus important et un coût moindre.","s":0},{"q":"Quels effets indésirables l'instillation de sérum physiologique peut-elle provoquer ?","o":["Toux excessive et bronchospasme","Tachycardie pendant l'instillation","Baisse de la saturation en oxygène","Hausse de la pression intracrânienne","Hypotension artérielle sévère"],"r":[0,1,2,3],"e":"Ces cinq effets indésirables doivent être pesés avant toute instillation, dont la quantité reste de 2 mL, et en tout cas moins de 10 mL.","s":0},{"q":"Quels éléments composent le montage d'aspiration ?","o":["Un bocal collecteur, réservoir des sécrétions","Une tubulure de connexion pour la sonde","Un manomètre de pression négative","Un humidificateur chauffant sur le circuit"],"r":[0,1,2],"e":"Trois éléments composent le montage.","s":0},{"q":"Quelles caractéristiques peut présenter une sonde d'aspiration ?","o":["Un ou plusieurs orifices","Des valves de contrôle","Un ballonnet gonflable","Un filtre intégré"],"r":[0,1],"e":"La sonde peut comporter un ou plusieurs orifices et des valves de contrôle ; le choix du diamètre est capital.","s":0},{"q":"Quelles mesures d'asepsie encadrent l'aspiration ?","o":["Se laver les mains et désinfecter","Porter tablier ou blouse, masque et lunettes","Porter des gants stériles ou non stériles selon la politique locale","Porter systématiquement une charlotte"],"r":[0,1,2],"e":"Trois mesures, le choix entre gants stériles et non stériles devant être évalué au regard de la politique locale.","s":0},{"q":"Quelle est la première étape pour enfiler des gants stériles ?","o":["Retirer montres et bijoux, puis se laver les mains","Ouvrir l'emballage externe, puis l'emballage interne","Enfiler la main dominante, puis la main non dominante","Ajuster les gants, puis vérifier leur intégrité"],"r":0,"e":"Retirer montres et bijoux et se laver les mains précède l'ouverture de l'emballage, puis l'enfilage de la main dominante.","s":0},{"q":"Comment saisit-on le premier gant stérile ?","o":["Par le bord du poignet, avec 3 doigts, côté intérieur","Par la paume, avec toute la main, côté extérieur","Par le bout des doigts, avec une pince stérile","Par le bord du poignet, avec 2 doigts, côté extérieur"],"r":0,"e":"On saisit le bord du poignet avec les trois premiers doigts de la main non dominante, en ne touchant que la surface interne. Ce sont les trois premiers doigts de la main non dominante.","s":0},{"q":"Quelle est la règle d'or lors de la manipulation des gants stériles ?","o":["Ne jamais toucher le stérile avec du non stérile","Toujours enfiler la main non dominante en premier","Ne toucher que la surface externe des deux gants","Ne plus ajuster les gants une fois enfilés"],"r":0,"e":"C'est la règle fondamentale : ne jamais mettre en contact surface stérile et surface non stérile.","s":0},{"q":"Quelles voies d'aspiration passent par une sonde endotrachéale ?","o":["La voie nasotrachéale","La voie orotrachéale","La voie oropharyngée","La trachéotomie"],"r":[0,1],"e":"Nasotrachéale et orotrachéale passent par la sonde endotrachéale. La trachéotomie utilise la canule de trachéotomie.","s":0},{"q":"Comment introduit-on la sonde dans la voie aérienne ?","o":["En induisant une flexion à l'extrémité à l'entrée","Selon un trajet linéaire descendant","Sans appliquer le vide avec le pouce","En appliquant immédiatement la pression négative"],"r":[0,1,2],"e":"Entrée avec flexion de l'extrémité, descente linéaire sans vide. La pression négative n'est appliquée qu'au retrait.","s":0},{"q":"Que signifie une résistance rencontrée pendant la descente de la sonde ?","o":["La sonde bute sur la carène ou un bouchon","La sonde est trop grosse pour la trachée","Le vide appliqué est réglé trop fort","Le patient déclenche un réflexe de toux"],"r":0,"e":"La résistance correspond à la carène ou à un bouchon de sécrétions : il faut alors se retirer de 1 cm avant d'appliquer la pression négative.","s":0},{"q":"Selon quel trajet retire-t-on la sonde ?","o":["En spirale ascendante, vide appliqué au pouce","En ligne droite rapide, sans aucun vide","En spirale descendante, vide appliqué au pouce","Par rotations complètes, en vide continu"],"r":0,"e":"Le retrait se fait selon un trajet spiralé ascendant avec application du vide, en 15 secondes au maximum.","s":0},{"q":"Quelle est la pression de vide actuellement recommandée chez l'adulte, et son maximum ?","o":["−80 mmHg recommandé, −200 mmHg au maximum","−100 à −150 mmHg recommandé, −200 mmHg au maximum","−200 mmHg recommandé, −300 mmHg au maximum","−50 mmHg recommandé, −100 mmHg au maximum"],"r":0,"e":"Recommandation actuelle : −80 mmHg. Ancienne recommandation : −100 à −150 mmHg. Maximum : −200 mmHg.","s":0},{"q":"Quelle règle encadre le diamètre du cathéter d'aspiration ?","o":["Il n'occlut pas plus de 50 % de la lumière","Il occupe au moins 80 % de la lumière","Il fait la moitié du diamètre de la narine","Il est le plus large que tolère le patient"],"r":0,"e":"Le diamètre ne doit pas occlure plus de 50 % de la lumière de la voie aérienne.","s":0},{"q":"Combien de temps pré-oxygène-t-on et à quelle fraction ?","o":["1 minute à 100 %","30 secondes à 50 %","5 minutes à 100 %","Pas de pré-oxygénation"],"r":0,"e":"1 minute d'oxygénation à 100 % — sauf en cas de pression intracrânienne élevée, où il ne faut pas pré-oxygéner.","s":0},{"q":"Sur quelles références l'aspiration en pratique s'appuie-t-elle ?","o":["AARC, Respiratory Care, 2004, 2010 et 2022","Gosselink et al., ERS, 2008 et 2012","Stiller, Critical Care, 2000 et 2013","Pryor et Webber, Physiotherapy, 1993 et 1998"],"r":0,"e":"Les trois guidelines de l'American Association for Respiratory Care (2004, 2010, 2022) encadrent la pratique de l'aspiration.","s":0},{"q":"Quel signe radiologique peut indiquer la nécessité d'aspirer ?","o":["Une atélectasie à la radiographie","Un pneumothorax à la radiographie","Un épanchement pleural de faible abondance","Une hyperinsufflation des deux champs"],"r":0,"e":"Des sécrétions visibles dans une voie aérienne artificielle ou une atélectasie à la radiographie figurent parmi les indications d'aspiration.","s":0},{"q":"Comment définit-on l'auscultation pulmonaire ?","o":["L'écoute au stéthoscope des sons pulmonaires transmis à la paroi","La palpation des vibrations transmises à la paroi thoracique","La percussion des champs pulmonaires pour juger de leur sonorité","L'analyse des gaz du sang pour juger de l'hématose"],"r":0,"e":"Ces sons résultent des vibrations ayant pour origine le poumon et les voies aériennes.","s":1},{"q":"À quoi sert le pavillon étroit et conique du stéthoscope ?","o":["À écouter les sons de basse fréquence, comme le cœur","À écouter les sons de haute fréquence, comme les sibilants","À filtrer les bruits ambiants pendant l'écoute","À amplifier le murmure vésiculaire aux bases"],"r":0,"e":"Le pavillon large, muni d'une membrane, sert aux sons de fréquence plus élevée.","s":1},{"q":"Pourquoi les tubes de conduction doivent-ils être de bonne qualité ?","o":["Pour garantir l'exclusion des bruits ambiants","Pour amplifier les sons graves","Pour éviter la douleur auriculaire","Pour permettre l'auscultation à distance"],"r":0,"e":"Le stéthoscope comprend aussi la lyre, les embouts auriculaires et le pavillon.","s":1},{"q":"À quoi sert l'auscultation en kinésithérapie respiratoire ?","o":["À évaluer, surveiller et guider l'intervention","À remplacer la radiographie, la spirométrie et la gazométrie","À mesurer les volumes, les débits et la compliance","À déterminer la saturation, le pH et les bicarbonates"],"r":0,"e":"C'est un moyen d'évaluation à part entière. Elle permet aussi de peser les risques de l'intervention.","s":1},{"q":"Quel bruit respiratoire normal présente un rapport inspiration >> expiration ?","o":["Le murmure vésiculaire","Le bruit trachéal","Le bruit bronchique","Le bruit broncho-vésiculaire"],"r":0,"e":"Il s'entend sur le tissu pulmonaire périphérique et son ton est grave.","s":1},{"q":"Où entend-on le bruit bronchique ?","o":["Sur le manubrium, entre les clavicules ou les scapulas","Sur le tissu pulmonaire périphérique, aux deux bases","Sur la trachée cervicale, au-dessus du manubrium","Aux bases pulmonaires, sous la pointe des scapulas"],"r":0,"e":"Son rapport est inspiration < expiration et son ton est aigu.","s":1},{"q":"Quel bruit normal a un ton moyen et un rapport inspiration = expiration au niveau des grandes voies près du sternum ?","o":["Le bruit broncho-vésiculaire","Le bruit trachéal","Le murmure vésiculaire","Le bruit bronchique"],"r":0,"e":"Le bruit trachéal a aussi I = E mais un ton aigu, et s'entend sur la trachée.","s":1},{"q":"Selon Postiaux, comment sont générés les bruits respiratoires normaux ?","o":["Dans les voies centrales et moyennes, filtrés par le parenchyme","Dans les alvéoles, puis amplifiés par le parenchyme","Dans la plèvre, au frottement des deux feuillets","Dans le larynx, puis transmis le long de la trachée cervicale"],"r":0,"e":"Leur timbre est rude, de basse fréquence.","s":1},{"q":"Quels facteurs font varier l'intensité des bruits respiratoires ?","o":["Débit, volume d'air interposé, position et lieu d'écoute","Âge, sexe, taille et poids du patient seulement","Température, humidité et bruit de la pièce seulement","Type, marque et longueur du stéthoscope seulement"],"r":0,"e":"Ils peuvent être normaux, augmentés, diminués ou absents.","s":1},{"q":"Dans quelles situations les bruits respiratoires sont-ils diminués ?","o":["Obstruction bronchique, emphysème, fibrose, pleurésie","Effort physique, début de crise d'asthme, fièvre","Pneumonie avec condensation, cavité, abcès","Enfant sain, sujet mince, paroi thoracique fine"],"r":0,"e":"L'effort et le début d'une crise les accentuent au contraire. L'œdème et l'hémothorax les diminuent aussi.","s":1},{"q":"Quel souffle est le signe classique de la pneumonie ?","o":["Le souffle tubaire, de condensation","Le souffle pleurétique, d'épanchement","Le souffle amphorique, de pneumothorax","Le souffle cavitaire, d'excavation"],"r":0,"e":"C'est le plus fréquent, surtout inspiratoire.","s":1},{"q":"Quel souffle est surtout expiratoire ?","o":["Le souffle pleurétique","Le souffle tubaire","Le souffle cavitaire","Le murmure rude"],"r":0,"e":"Les souffles tubaire et cavitaire sont surtout inspiratoires.","s":1},{"q":"Comment Postiaux caractérise-t-il les bruits respiratoires bronchiques ?","o":["Timbre clair, aigu, peu filtré par un parenchyme dense","Timbre rude, grave, bien filtré par un parenchyme sain","Bruit discontinu, bref, de moins de 30 ms","Bruit musical, continu, de plus de 30 ms"],"r":0,"e":"Ils sont normaux chez l'enfant, pathologiques dans la pneumonie et les cavités à paroi épaissie.","s":1},{"q":"Chez qui les bruits respiratoires bronchiques sont-ils considérés comme normaux ?","o":["Chez l'enfant","Chez le sujet âgé","Chez le patient BPCO","Chez le sportif"],"r":0,"e":"Chez l'adulte, ils évoquent une pneumonie ou une cavité à paroi épaissie.","s":1},{"q":"Qu'est-ce qui produit les sibilants ?","o":["L'air passant dans des bronches rétrécies ou encombrées","Les alvéoles qui se déplissent en fin d'inspiration","Les feuillets pleuraux qui frottent l'un contre l'autre","Les bulles de sécrétions qui éclatent dans les bronchioles"],"r":0,"e":"Ils sont de tonalité aiguë et fine, et classés parmi les bruits adventices continus.","s":1},{"q":"Que traduisent des sibilants polyphoniques ?","o":["Une obstruction diffuse des voies aériennes","Une sténose localisée d'une seule bronche","Une alvéolite fibrosante des deux bases","Un épanchement pleural de grande abondance"],"r":0,"e":"Les monophoniques traduisent une sténose localisée.","s":1},{"q":"Que traduisent des sibilants monophoniques dispersés ?","o":["Un asthme","Une alvéolite fibrosante","Une pneumonie","Des bronchectasies"],"r":0,"e":"Les monophoniques séquentiels évoquent une alvéolite fibrosante.","s":1},{"q":"Que traduisent des sibilants monophoniques séquentiels ?","o":["Une alvéolite fibrosante","Un asthme","Une obstruction diffuse","Un pneumothorax"],"r":0,"e":"Les monophoniques dispersés évoquent plutôt l'asthme.","s":1},{"q":"Quelles sont les phases du cycle respiratoire utilisées pour caractériser les sibilants ?","o":["Proto-, méso-, télo- ou holophasiques","Initiaux, moyens, terminaux ou continus","Inspiratoires, expiratoires ou biphasiques","Précoces, tardifs, intermittents ou permanents"],"r":0,"e":"On note aussi la position-dépendance et la kinésio-dépendance.","s":1},{"q":"Que traduisent les ronchi ?","o":["Une obstruction des voies aériennes proximales","Une obstruction des voies aériennes distales","Une obstruction des voies aériennes périphériques","Une inflammation pleurale"],"r":0,"e":"Ils sont de tonalité grave, se modifient avec la toux et sont audibles dans les deux temps respiratoires.","s":1},{"q":"Comment Postiaux nomme-t-il les ronchi ?","o":["Râles de basse fréquence","Râles de moyenne fréquence","Râles de haute fréquence","Râles fins"],"r":0,"e":"Les râles sous-crépitants correspondent aux râles de moyenne fréquence.","s":1},{"q":"Quel bruit correspond à un son gargouillant par bullage de l'air dans les bronchioles remplies de sécrétions ?","o":["Les râles sous-crépitants","Les râles crépitants","Les sibilants","Le frottement pleural"],"r":0,"e":"Ils sont typiques des bronchectasies et traduisent une obstruction des voies aériennes distales.","s":1},{"q":"Comment décrit-on les râles crépitants ?","o":["Des cheveux frottés entre les doigts, en fin d'inspiration","Un gargouillement grave et humide, aux deux temps du cycle","Un sifflement aigu, surtout en fin d'expiration","Un frottement de cuir neuf, aux deux temps du cycle"],"r":0,"e":"Ils correspondent au déplissement des alvéoles et traduisent une obstruction des voies aériennes périphériques.","s":1},{"q":"À quoi correspondent les râles de haute fréquence de Postiaux ?","o":["Aux râles crépitants, dits râles fins","Aux ronchi, dits gros râles bronchiques","Aux sous-crépitants, dits râles moyens","Aux sibilants, dits râles musicaux"],"r":0,"e":"Ils traduisent une obstruction des voies aériennes périphériques.","s":1},{"q":"Que traduit un frottement pleural ?","o":["Une inflammation ou réaction pleurale","Une inflammation du péricarde","Une obstruction des grosses bronches","Une consolidation alvéolaire étendue"],"r":0,"e":"Le frottement péricardique traduit une inflammation péricardique.","s":1},{"q":"Que traduit un sifflement oral à l'auscultation buccale ?","o":["Un rétrécissement de la lumière bronchique","Une accumulation de sécrétions trachéales","Une pneumonie avec condensation lobaire","Un épanchement pleural à la base"],"r":0,"e":"L'encombrement oral traduit une accumulation de sécrétions dans la trachée et les grosses bronches.","s":1},{"q":"Que signifie une égophonie ?","o":["Un épanchement pleural","Une pneumonie","Un pneumothorax","Une bronchectasie"],"r":0,"e":"Elle se caractérise par une tonalité de voix de chèvre ou de polichinelle.","s":1},{"q":"Que signifie une pectoriloquie ?","o":["Une pneumonie : mots et syllabes nettement distincts","Un épanchement : voix chevrotante de polichinelle","Un état normal : mots indistincts et voix étouffée","Un emphysème : voix très affaiblie, presque abolie"],"r":0,"e":"Normalement, on ne distingue pas les mots à l'auscultation de la voix.","s":1},{"q":"Quelle est la séquence d'auscultation recommandée ?","o":["Bruits à la bouche, puis thoraciques, puis adventices","Bruits adventices, puis thoraciques, puis à la bouche","Bruits thoraciques, puis adventices, puis à la bouche","Percussion, puis voix, puis bruits thoraciques"],"r":0,"e":"Elle se pratique assis, puis en décubitus latéral.","s":1},{"q":"Pourquoi la respiration doit-elle être profonde mais entrecoupée d'intervalles ?","o":["À cause du risque d'alcalose respiratoire","Pour éviter la fatigue des muscles respiratoires","Pour limiter la douleur thoracique du patient","Pour améliorer la perfusion des bases"],"r":0,"e":"L'auscultation doit être systématique, en comparant chaque point de façon controlatérale.","s":1},{"q":"Quelles parties du stéthoscope assurent la transmission vers l'oreille ?","o":["La lyre, partie métallique","Les embouts auriculaires","Les tubes de conduction","Le pavillon à membrane"],"r":[0,1],"e":"Lyre et embouts auriculaires transmettent vers l'oreille ; les tubes de conduction, de bonne qualité, garantissent l'exclusion des bruits ambiants.","s":1},{"q":"Où entend-on le bruit trachéal et quel est son rapport I/E ?","o":["Sur la trachée, avec inspiration = expiration","Sur le manubrium, avec inspiration < expiration","Au niveau du tissu périphérique, avec inspiration >> expiration","Entre les scapulas, avec inspiration = expiration"],"r":0,"e":"Trachéal : sur la trachée, I = E, ton aigu. Bronchique : manubrium, I < E, aigu. Broncho-vésiculaire : près du sternum et entre les scapulas, I = E, moyen. Murmure vésiculaire : périphérie, I >> E, grave.","s":1},{"q":"Où entend-on le murmure vésiculaire ?","o":["Sur le tissu pulmonaire, en périphérie","Sur la trachée, au-dessus du sternum","Sur le manubrium, en regard du sternum","Entre les clavicules, sur la ligne médiane"],"r":0,"e":"Le murmure vésiculaire s'entend au niveau du tissu pulmonaire périphérique, avec un ton grave et une inspiration bien plus longue que l'expiration.","s":1},{"q":"Quels états peuvent prendre les bruits respiratoires normaux ?","o":["Normaux","Augmentés","Diminués","Absents","Bronchiques"],"r":[0,1,2,3],"e":"Les bruits respiratoires normaux peuvent être normaux, augmentés, diminués ou absents.","s":1},{"q":"Dans quelles situations les bruits respiratoires sont-ils accentués ?","o":["À l'effort","Au début d'une crise","En cas d'emphysème","En cas de pleurésie"],"r":[0,1],"e":"Effort et début de crise accentuent les bruits. Emphysème, fibrose, œdème, pleurésie, hémothorax et limitation de l'expansion les diminuent.","s":1},{"q":"Quelles situations diminuent les bruits respiratoires ?","o":["Obstruction bronchique","Emphysème et fibrose","Œdème, pleurésie et hémothorax","Obésité ou parésie limitant l'expansion","Effort physique intense"],"r":[0,1,2,3],"e":"Toutes ces situations diminuent l'intensité des bruits respiratoires.","s":1},{"q":"Quels souffles sont surtout inspiratoires ?","o":["Le souffle tubaire ou de condensation","Le souffle cavitaire","Le souffle pleurétique","Le souffle amphorique"],"r":[0,1],"e":"Tubaire et cavitaire sont surtout inspiratoires ; le souffle pleurétique est surtout expiratoire.","s":1},{"q":"Dans quelles situations pathologiques entend-on des bruits respiratoires bronchiques ?","o":["Pneumonie avec condensation","Cavité à paroi épaissie","Emphysème pulmonaire diffus","Pneumothorax complet"],"r":[0,1],"e":"Pneumonie et cavité à paroi épaissie. Chez l'enfant, ces bruits peuvent être normaux. Par exemple un abcès pulmonaire.","s":1},{"q":"Pourquoi les bruits bronchiques sont-ils peu filtrés en cas de condensation ?","o":["Le parenchyme dense transmet mieux les hautes fréquences","L'air remplace le parenchyme et amplifie les sons","La plèvre épaissie conduit mieux les vibrations sonores","Le débit d'air augmente dans la zone condensée"],"r":0,"e":"Les bruits bronchiques ont un timbre clair, généré dans les voies centrales et peu filtré par le parenchyme densifié (consolidé) — contrairement au parenchyme sain qui filtre.","s":1},{"q":"Comment se comportent les ronchi à la toux et dans le cycle respiratoire ?","o":["Ils se modifient avec la toux","Ils sont audibles dans les deux temps respiratoires","Ils disparaissent à l'inspiration","Ils ne sont audibles qu'à l'expiration"],"r":[0,1],"e":"Les ronchi, de tonalité grave, se modifient avec la toux et s'entendent aux deux temps ; ils traduisent une obstruction des voies aériennes proximales.","s":1},{"q":"Quelles caractéristiques, en plus de la tonalité, décrivent les sibilants ?","o":["La phase du cycle respiratoire","La position-dépendance","La kinésio-dépendance","La modification par la toux"],"r":[0,1,2],"e":"Phase du cycle, position-dépendance et kinésio-dépendance. C'est le ronchus qui se modifie avec la toux. Phases : protophasiques, mésophasiques, télophasiques ou holophasiques.","s":1},{"q":"Que traduisent des sibilants monophoniques ?","o":["Une sténose localisée d'une bronche","Une obstruction diffuse des voies aériennes","Un épanchement pleural abondant","Une condensation pulmonaire lobaire"],"r":0,"e":"Monophoniques : sténose localisée. Polyphoniques : obstruction diffuse. Monophoniques dispersés : asthme. Monophoniques séquentiels : alvéolite fibrosante.","s":1},{"q":"Que traduisent les râles sous-crépitants, ou râles de moyenne fréquence ?","o":["Une obstruction des voies aériennes distales","Une obstruction des voies aériennes périphériques","Une obstruction proximale","Une inflammation pleurale"],"r":0,"e":"Sous-crépitants (moyenne fréquence) : obstruction distale, typiquement dans les bronchectasies. Crépitants (haute fréquence) : obstruction périphérique.","s":1},{"q":"À quel moment du cycle entend-on les râles crépitants et quel en est le mécanisme ?","o":["En fin d'inspiration, par déplissement alvéolaire","En début d'expiration, par bullage de sécrétions","Aux deux temps, par sténose d'une bronche","En continu, par frottement des feuillets"],"r":0,"e":"Les crépitants s'entendent en fin d'inspiration, comme si l'on frottait des cheveux entre les doigts : c'est le déplissement des alvéoles.","s":1},{"q":"Que traduit un frottement péricardique ?","o":["Une inflammation péricardique","Une inflammation ou réaction pleurale","Une obstruction bronchique","Une consolidation parenchymateuse"],"r":0,"e":"Frottement pleural : inflammation ou réaction pleurale. Frottement péricardique : inflammation péricardique. Ce sont les deux bruits extra-pulmonaires.","s":1},{"q":"Que traduit un encombrement oral à l'auscultation buccale ?","o":["Des sécrétions dans la trachée et les grosses bronches","Un rétrécissement de la lumière des petites bronches","Une consolidation alvéolaire d'un lobe entier","Un épanchement pleural abondant à la base"],"r":0,"e":"Encombrement oral : sécrétions dans la trachée et les grosses bronches. Sifflement oral : rétrécissement de la lumière bronchique. Le patient expire vers le stéthoscope.","s":1},{"q":"Que signifie une bronchophonie ?","o":["Une voix entendue intensément : pneumonie","Des mots indistincts : situation normale","Des syllabes nettes : emphysème","Une voix de chèvre : pneumothorax"],"r":0,"e":"Bronchophonie : voix entendue intensément → pneumonie. Pectoriloquie : mots et syllabes distincts → pneumonie. Égophonie : voix de chèvre ou de polichinelle → épanchement pleural.","s":1},{"q":"Quelles sont les deux étapes d'analyse de l'auscultation ?","o":["Exclure les bruits extra-thoraciques","Analyser tout le champ pulmonaire","Mesurer la saturation au doigt","Réaliser une gazométrie artérielle"],"r":[0,1],"e":"Première étape : exclure les bruits extra-thoraciques. Seconde : analyser l'ensemble du champ pulmonaire. Le champ pulmonaire s'analyse en avant, latéralement et en arrière.","s":1},{"q":"Dans quelles conditions le patient doit-il être ausculté ?","o":["Assis, puis en décubitus latéral","Détendu et torse nu","Dans un environnement silencieux","La bouche ouverte","En décubitus ventral strict"],"r":[0,1,2,3],"e":"Les quatre conditions sont précisées ; la bouche ouverte potentialise le son écouté.","s":1},{"q":"Pourquoi l'auscultation doit-elle comparer chaque point de façon controlatérale ?","o":["Parce que la comparaison révèle les asymétries","Parce que le stéthoscope se déplace plus vite","Parce que cela fait gagner du temps au patient","Parce que cela évite l'alcalose respiratoire"],"r":0,"e":"L'auscultation doit être systématique, en comparant chaque point de façon controlatérale. C'est l'espacement des respirations profondes qui prévient l'alcalose.","s":1},{"q":"Quand faut-il rééduquer le schéma et le rythme ventilatoires ?","o":["Lorsqu'ils ne sont pas efficients","Systématiquement chez tout patient","Uniquement en post-opératoire","Uniquement chez le patient ventilé"],"r":0,"e":"Le choix des stratégies dépend des altérations fonctionnelles identifiées à l'évaluation.","s":2},{"q":"Quelle part de la consommation totale d'oxygène un individu sain consacre-t-il au travail musculaire respiratoire ?","o":["Environ 5 %","Environ 10 %","Environ 25 %","Environ 50 %"],"r":0,"e":"Il utilise par ailleurs environ 10 % de sa capacité vitale.","s":2},{"q":"Quelle part de sa capacité vitale un individu sain utilise-t-il ?","o":["Environ 10 %","Environ 5 %","Environ 30 %","Environ 60 %"],"r":0,"e":"Chez un patient dysfonctionnel, la capacité vitale peut être réduite et la consommation d'oxygène augmentée.","s":2},{"q":"Pourquoi la consommation d'oxygène augmente-t-elle en cas de dysfonction respiratoire ?","o":["Par la musculature accessoire, l'effort et la toux","Par la baisse du métabolisme, du tonus et de la toux","Par la relaxation, le repos et le sommeil profond","Par la capacité vitale, le débit et la compliance accrus"],"r":0,"e":"La capacité vitale peut par ailleurs être réduite.","s":2},{"q":"Quels sont les trois schémas respiratoires décrits ?","o":["Costal supérieur, costal inférieur, abdomino-diaphragmatique","Eupnée, tachypnée, polypnée et bradypnée","Superficiel, intermédiaire, profond, de type apneustique","Nasal, buccal, nasobuccal et trachéal"],"r":0,"e":"Les rythmes sont l'eupnée, la tachypnée, la polypnée, la bradypnée et le Cheyne-Stokes.","s":2},{"q":"Le bronchospasme figure-t-il parmi les indications du contrôle respiratoire ?","o":["Oui, notamment dans l'asthme","Non, c'est une contre-indication","Uniquement chez l'enfant","Uniquement en post-opératoire"],"r":0,"e":"Les indications comprennent aussi la douleur, l'anxiété et les syndromes restrictifs.","s":2},{"q":"Les fractures de côtes constituent-elles une indication du contrôle respiratoire ?","o":["Oui, c'est une indication","Non, c'est une contre-indication absolue","Oui, mais seulement après consolidation","Oui, mais seulement chez le sujet jeune"],"r":0,"e":"Les indications incluent aussi les dysfonctions de la clairance mucociliaire et les troubles métaboliques à répercussion respiratoire.","s":2},{"q":"Quel objectif du contrôle respiratoire concerne la sphère psychologique ?","o":["Donner au patient un sentiment d'auto-contrôle","Améliorer la ventilation des alvéoles","Diminuer le travail respiratoire global","Améliorer la clairance du mucus bronchique"],"r":0,"e":"La relaxation est aussi un objectif à part entière. Le patient y gagne aussi en confiance en soi.","s":2},{"q":"Quel objectif du contrôle respiratoire porte sur les muscles respiratoires ?","o":["Améliorer leur force, leur coordination, leur efficience","Augmenter leur masse, leur volume, leur section","Réduire leur tonus, leur activité, leur recrutement","Accroître leur raideur, leur tension, leur rigidité"],"r":0,"e":"Il s'ajoute à la diminution du travail respiratoire et à l'amélioration de la ventilation alvéolaire.","s":2},{"q":"Quelle stratégie est privilégiée dans les dysfonctions pulmonaires primaires ?","o":["Relâcher les accessoires et faciliter le diaphragme","Renforcer exclusivement les muscles accessoires","Équilibrer le diaphragme et les muscles accessoires","Bloquer le diaphragme pour solliciter les accessoires"],"r":0,"e":"Dans les dysfonctions secondaires, on cherche l'équilibre entre respiration diaphragmatique et musculature accessoire pour augmenter la capacité vitale.","s":2},{"q":"Quelle consigne donne-t-on lors de la 1ʳᵉ phase de l'expiration à lèvres pincées ?","o":["Expirer lentement sans forcer, en laissant l'air sortir","Expirer vite et fort, en vidant les poumons à fond","Tenir une apnée de 5 secondes, en gardant les lèvres closes","Inspirer par la bouche, en gonflant bien les joues"],"r":0,"e":"Cette phase entraîne une diminution de la fréquence respiratoire.","s":2},{"q":"Quel est l'effet de la 1ʳᵉ phase de l'expiration à lèvres pincées ?","o":["Une diminution de la fréquence respiratoire","Une augmentation de la pression endo-bronchique","Un soulagement immédiat du bronchospasme","Une augmentation du volume résiduel"],"r":0,"e":"L'augmentation de la pression endo-bronchique et le soulagement du bronchospasme relèvent de la 2ᵉ phase.","s":2},{"q":"En quoi consiste la 2ᵉ phase de l'expiration à lèvres pincées ?","o":["Une apnée inspiratoire de 1 à 2 s, puis l'expiration pincée","Une expiration forcée de 1 à 2 s, puis une toux dirigée","Deux inspirations successives, puis une apnée de 5 s","Une apnée expiratoire de 10 s, puis une inspiration lente"],"r":0,"e":"Elle augmente la pression endo-bronchique et soulage le bronchospasme.","s":2},{"q":"Quelle position de repos classique est enseignée au patient ?","o":["La position du cocher","La position de Trendelenburg","Le décubitus ventral strict","La position debout jambes tendues"],"r":0,"e":"On y associe l'expiration à lèvres pincées et la respiration diaphragmatique.","s":2},{"q":"À qui s'adresse le sniffing ?","o":["Aux patients qui peinent à respirer avec le diaphragme","Aux patients en détresse respiratoire aiguë sévère","Aux patients intubés sous ventilation mécanique","Aux patients sans aucune dysfonction respiratoire"],"r":0,"e":"C'est une méthode simple et efficace pour enseigner la respiration diaphragmatique.","s":2},{"q":"Quelles positions sont possibles pour le sniffing ?","o":["Décubitus latéral, semi-Fowler ou assis dos appuyé","Décubitus ventral, à genoux ou debout sans appui","Debout, en fente avant ou assis sans dossier","Décubitus dorsal, jambes tendues ou bras levés"],"r":0,"e":"Le bassin est placé en légère bascule postérieure, genoux fléchis.","s":2},{"q":"Comment sont positionnés les membres supérieurs lors du sniffing ?","o":["En extension, adduction et rotation interne","En flexion, abduction et rotation externe","Croisés sur la poitrine","Au-dessus de la tête"],"r":0,"e":"Cette position correspond au schéma expiratoire des stratégies de ventilation-mouvement.","s":2},{"q":"Pourquoi demande-t-on au patient de placer les mains sur son diaphragme ?","o":["Pour fournir un stimulus proprioceptif","Pour bloquer l'expiration du patient","Pour renforcer les muscles abdominaux","Pour mesurer l'amplitude thoracique"],"r":0,"e":"C'est le préalable à la technique de sniffing.","s":2},{"q":"Quel est l'ordre des trois phases du sniffing ?","o":["Sniffer en 3 temps, puis en 2 temps, puis en une seule fois","Sniffer en 1 temps, puis en 2 temps, puis en 3 temps successifs","Sniffer en 2 temps, puis en 4 temps, puis en continu","Sniffer en continu pendant 3 minutes, puis récupérer au repos"],"r":0,"e":"L'expiration se fait toujours à lèvres pincées.","s":2},{"q":"Sur quel ton la consigne du sniffing doit-elle être donnée ?","o":["D'une voix calme et mélodieuse","D'une voix forte et rapide","Sans parler","Par écrit uniquement"],"r":0,"e":"Le calme de la consigne fait partie de la technique.","s":2},{"q":"Comment positionne-t-on le patient pour la mobilisation diaphragmatique ?","o":["Latéral ou semi-Fowler, genoux fléchis, bassin en rétroversion","Ventral, jambes tendues, bassin en antéversion, bras le long du corps","Assis, tronc penché en arrière, jambes tendues","Debout, bras levés, bassin en position neutre"],"r":0,"e":"Les genoux fléchis relâchent les muscles abdominaux.","s":2},{"q":"Que fait le kinésithérapeute avec sa main pendant la mobilisation diaphragmatique ?","o":["Il accompagne et prolonge le temps expiratoire","Il comprime le thorax pendant l'inspiration","Il bloque le mouvement des côtes inférieures","Il applique une percussion rythmée sur le sternum"],"r":0,"e":"Un étirement initial en fin d'expiration facilite l'inspiration suivante.","s":2},{"q":"Quelle consigne verbale accompagne la mobilisation diaphragmatique ?","o":["« Respirez dans ma main »","« Expirez le plus fort possible »","« Bloquez votre respiration »","« Toussez trois fois »"],"r":0,"e":"Elle suit l'étirement réalisé en fin d'expiration.","s":2},{"q":"Comment progresse la mobilisation diaphragmatique ?","o":["Vers la position assise, puis debout, puis à la marche","Vers le décubitus, en restant toujours allongé sur le dos","Vers le décubitus ventral, puis vers la position quatre pattes","Vers la position assise, sans aller plus loin"],"r":0,"e":"Le patient est encouragé à continuer à s'exercer seul.","s":2},{"q":"Quelle consigne donne-t-on au patient pour monter les escaliers ?","o":["S'arrêter pour inspirer, puis expirer en montant 1 ou 2 marches","Inspirer en montant 1 ou 2 marches, puis expirer à l'arrêt","Monter en apnée, puis souffler une fois sur le palier","Monter le plus vite possible, puis récupérer en haut"],"r":0,"e":"Le contrôle respiratoire s'apprend aussi pendant la marche.","s":2},{"q":"Quand utilise-t-on l'inhibition costale supérieure ?","o":["Seulement si les autres techniques manuelles échouent","En première intention, avant toute autre technique","Chez tout patient atteint de BPCO, d'emblée","Systématiquement avant chaque séance de sniffing"],"r":0,"e":"Elle s'utilise habituellement en association avec la mobilisation diaphragmatique.","s":2},{"q":"Quelle MMT facilite l'excursion diaphragmatique ?","o":["La MMT costale inférieure","La MMT costale supérieure","La MMT costale moyenne","La MMT sternale"],"r":0,"e":"La MMT costale moyenne recrute principalement les intercostaux externes.","s":2},{"q":"Parmi ces questions d'évaluation, laquelle guide le choix de la stratégie ventilatoire ?","o":["La ventilation limite-t-elle sa mobilité ?","Le patient est-il à jour de ses vaccins ?","Quel est son groupe sanguin et son rhésus ?","Quel est son IMC, et lui seul ?"],"r":0,"e":"On demande aussi s'il a plus de difficulté à inspirer ou à expirer et s'il utilise la musculature accessoire.","s":2},{"q":"L'insuffisance cardiaque congestive est-elle une indication du contrôle respiratoire ?","o":["Oui, comme l'œdème aigu du poumon","Non, c'est une contre-indication","Oui, mais seulement en phase aiguë","Non, sauf chez l'enfant"],"r":0,"e":"Les indications recouvrent également l'anxiété et la douleur. L'œdème aigu du poumon et l'embolie pulmonaire en sont aussi.","s":2},{"q":"Quel objectif relie contrôle respiratoire et désobstruction ?","o":["Améliorer la clairance mucociliaire par une toux efficace","Augmenter le volume résiduel par une apnée prolongée","Réduire la capacité vitale par une expiration freinée","Diminuer la ventilation alvéolaire par un rythme lent"],"r":0,"e":"Le contrôle respiratoire vise aussi à diminuer le travail respiratoire et à favoriser la relaxation.","s":2},{"q":"Que peut-il arriver à la capacité vitale et à la consommation d'oxygène en cas de dysfonction respiratoire ?","o":["La capacité vitale peut diminuer","La consommation d'oxygène peut augmenter","Les deux restent strictement stables","La capacité vitale peut augmenter"],"r":[0,1],"e":"En cas de dysfonction, la capacité vitale se réduit et la consommation d'oxygène augmente, du fait du recours à la musculature accessoire, de l'effort respiratoire et de la toux.","s":2},{"q":"Quels rythmes respiratoires sont décrits dans ce cours ?","o":["Eupnée et tachypnée","Polypnée rapide","Bradypnée lente","Cheyne-Stokes","Respiration de Kussmaul"],"r":[0,1,2,3],"e":"Cinq rythmes sont listés, aux côtés des trois schémas : costal supérieur, costal inférieur et abdomino-diaphragmatique.","s":2},{"q":"Quelles dysfonctions constituent des indications au contrôle respiratoire ?","o":["Dysfonctions pulmonaires primaires ou secondaires","Douleur chirurgicale, traumatique ou liée à la maladie","Anxiété liée à la dyspnée","Troubles de la clairance et syndromes restrictifs","Hypertension artérielle essentielle"],"r":[0,1,2,3],"e":"Ces indications s'ajoutent au bronchospasme, aux fractures de côtes, à l'insuffisance cardiaque congestive, aux patients ventilés avec stimulus respiratoire et aux troubles métaboliques.","s":2},{"q":"Quels objectifs le contrôle respiratoire poursuit-il ?","o":["Diminuer le travail respiratoire","Améliorer la ventilation alvéolaire","Améliorer la clairance par la toux","Favoriser la relaxation","Dépasser la capacité pulmonaire prédite"],"r":[0,1,2,3],"e":"S'y ajoutent l'amélioration de la force, coordination et efficience des muscles respiratoires, et le sentiment d'auto-contrôle du patient.","s":2},{"q":"Quelles questions guident l'évaluation avant de choisir une stratégie ventilatoire ?","o":["Le patient a-t-il plus de difficulté à inspirer ou à expirer ?","Présente-t-il une séquence inspiratoire normale ?","Utilise-t-il la musculature accessoire ?","A-t-il des difficultés à parler ou à tousser ?","La ventilation limite-t-elle sa mobilité ?","Quel est le score au test de marche de 6 minutes ?"],"r":[0,1,2,3,4],"e":"Ces cinq questions orientent le choix des stratégies selon les altérations fonctionnelles identifiées.","s":2},{"q":"Quelle stratégie privilégie-t-on dans les dysfonctions pulmonaires secondaires ?","o":["Équilibrer diaphragme et accessoires, pour la capacité vitale","Relâcher les accessoires, pour faciliter le diaphragme seul","Inhiber les costaux supérieurs, à chaque séance","Interdire les accessoires, en toute circonstance"],"r":0,"e":"Primaires : relâchement des accessoires et facilitation diaphragmatique. Secondaires : équilibre entre diaphragme et accessoires pour augmenter la capacité vitale.","s":2},{"q":"Quelle est la durée de l'apnée inspiratoire dans la 2ᵉ phase de l'expiration à lèvres pincées ?","o":["1 à 2 secondes","5 secondes","10 secondes","Aucune apnée"],"r":0,"e":"Une apnée inspiratoire de 1 à 2 secondes précède l'expiration à lèvres pincées, ce qui augmente la pression endo-bronchique et soulage le bronchospasme.","s":2},{"q":"Qu'associe-t-on à l'apprentissage des positions de repos ?","o":["L'expiration à lèvres pincées","La respiration diaphragmatique","L'inhibition costale supérieure","La toux dirigée"],"r":[0,1],"e":"Aux positions de repos, dont la position du cocher, on associe l'apprentissage de l'expiration à lèvres pincées et de la respiration diaphragmatique.","s":2},{"q":"Comment positionne-t-on le bassin et les genoux pour le sniffing ?","o":["Bassin en légère bascule postérieure, genoux fléchis","Bassin en légère bascule antérieure, genoux tendus","Bassin en position neutre, genoux tendus","Bassin en rotation, genoux croisés l'un sur l'autre"],"r":0,"e":"Bassin en légère bascule postérieure et genoux fléchis, ce qui relâche la paroi abdominale.","s":2},{"q":"Quelles positions sont proposées pour le sniffing ?","o":["Décubitus latéral","Semi-Fowler","Assis avec le dos appuyé","Debout sans appui"],"r":[0,1,2],"e":"Décubitus latéral, semi-Fowler ou assis dos appuyé. On positionne aussi la tête avec des coussins, en étant attentif à sa position.","s":2},{"q":"Quelle progression suit le nombre de temps du sniffing ?","o":["3 temps, puis 2 temps, puis une seule fois","1 temps, puis 2 temps, puis 3 temps","Toujours 3 temps, du début à la fin","Toujours une seule fois, sans progression"],"r":0,"e":"On sniffe d'abord en 3 temps, puis en 2 temps, puis en une seule fois — l'expiration se faisant toujours à lèvres pincées.","s":2},{"q":"Quel est l'effet de l'étirement réalisé en fin d'expiration lors de la mobilisation diaphragmatique ?","o":["Il facilite l'inspiration suivante","Il diminue la fréquence respiratoire","Il augmente la pression endo-bronchique","Il inhibe les intercostaux"],"r":0,"e":"En fin d'expiration, un étirement initial facilite l'inspiration suivante, accompagnée de la consigne « Respirez dans ma main ».","s":2},{"q":"Quelle progression suit la mobilisation diaphragmatique ?","o":["De la position couchée à assise","Puis vers la position debout","Puis pendant la marche","Puis pendant la course"],"r":[0,1,2],"e":"Couché → assis → debout → marche, avec pour consigne de se relâcher et de contrôler la respiration. Les membres supérieurs restent relâchés, avec relâchement et contrôle de la respiration à la marche.","s":2},{"q":"Quelle consigne donne-t-on pour monter les escaliers ?","o":["S'arrêter et inspirer, puis expirer en montant une ou deux marches","Inspirer en montant une ou deux marches, puis expirer à l'arrêt","Retenir sa respiration pendant toute la montée","Monter le plus vite possible, puis souffler en haut"],"r":0,"e":"Le patient s'arrête et inspire, puis expire en même temps qu'il monte une ou deux marches.","s":2},{"q":"Que recrute la mobilisation manuelle thoracique costale moyenne ?","o":["Les intercostaux externes","Le diaphragme, en partie costale","Les abdominaux obliques","Les scalènes et les SCM"],"r":0,"e":"La MMT costale inférieure facilite l'excursion diaphragmatique, la MMT costale moyenne recrute les intercostaux externes.","s":2},{"q":"Comment la mobilisation manuelle thoracique peut-elle être réalisée ?","o":["Bilatéralement","Unilatéralement","Uniquement en décubitus ventral","Uniquement debout"],"r":[0,1],"e":"La MMT est réalisable bilatéralement ou unilatéralement.","s":2},{"q":"Avec quelle technique l'inhibition costale supérieure s'utilise-t-elle habituellement ?","o":["La mobilisation diaphragmatique","Le sniffing","L'expiration à lèvres pincées","La toux dirigée"],"r":0,"e":"L'inhibition costale supérieure s'emploie habituellement en association avec la mobilisation diaphragmatique, et uniquement si les autres techniques manuelles ont échoué.","s":2},{"q":"Pourquoi demande-t-on une voix calme et mélodieuse pour guider le sniffing ?","o":["La consigne verbale aide au relâchement et à l'apprentissage","Le patient est souvent malentendant et doit se concentrer","La voix doit couvrir les bruits ambiants de la salle","La mélodie de la voix rythme la fréquence de l'expiration"],"r":0,"e":"La consigne du sniffing doit être donnée d'une voix calme et mélodieuse, ce qui favorise le relâchement et l'apprentissage.","s":2},{"q":"Que vise l'objectif « permettre au patient un sentiment d'auto-contrôle » ?","o":["Renforcer sa confiance en soi face à sa dysfonction","Réduire sa fréquence cardiaque au repos et à l'effort","Augmenter sa capacité vitale mesurée à la spirométrie","Diminuer la fréquence de sa toux"],"r":0,"e":"Cet objectif vise le sentiment d'auto-contrôle et la confiance en soi du patient face à sa dysfonction.","s":2},{"q":"Comment positionne-t-on les membres supérieurs lors du sniffing, et pourquoi ?","o":["Extension, adduction, rotation interne : moins d'accessoires","Abduction, rotation externe : plus d'expansion costale","Croisés sur la poitrine : appui pour les pectoraux","Au-dessus de la tête : ouverture maximale du thorax"],"r":0,"e":"Membres supérieurs en extension, adduction et rotation interne — position qui défavorise le recours à la musculature accessoire et facilite le travail diaphragmatique.","s":2},{"q":"Quelles sont les 4 étapes de la désobstruction des voies aériennes ?","o":["Fluidification, décollement, progression, expulsion","Inspection, palpation, percussion, auscultation","Aérosol, pression expiratoire, toux, aspiration","Évaluation, traitement, réévaluation, éducation"],"r":0,"e":"Ce sont des étapes séquentielles interdépendantes.","s":3},{"q":"Quelles techniques utilise-t-on chez un patient non coopérant ?","o":["Des techniques passives ou passives-assistées","Des techniques autonomes, réalisées sans aucune aide","Des techniques autonomes-assistées","Des techniques actives contre résistance manuelle"],"r":0,"e":"Chez le patient coopérant, on utilise des techniques autonomes ou autonomes-assistées.","s":3},{"q":"Quel facteur ne fait pas partie du choix de la technique de désobstruction ?","o":["Le groupe sanguin du patient","La localisation des sécrétions","La rhéologie des sécrétions","Le degré de collaboration"],"r":0,"e":"On considère aussi les comorbidités, l'âge et la dépense énergétique associée à la technique.","s":3},{"q":"Quelle technique de désobstruction des voies extra-thoraciques est réservée à l'enfant ?","o":["La DRR, désobstruction rhinopharyngée rétrograde","Le mouchage, narine par narine, avec du sérum","L'aspiration nasale, à la sonde, après instillation","L'ELTGOL, en décubitus latéral"],"r":0,"e":"Le rire et les pleurs sont également cités chez l'enfant.","s":3},{"q":"Avec quel instrument évalue-t-on objectivement l'efficacité de la toux ?","o":["Un Peak Flow Meter","Un spiromètre incitatif","Un manomètre de pressions respiratoires","Un oxymètre de pouls"],"r":0,"e":"Il mesure le Peak Cough Flow en L/min.","s":3},{"q":"Comment simule-t-on la toux au peak flow meter ?","o":["Par une expiration forcée, glotte fermée au départ","Par une expiration forcée, glotte grande ouverte","Par une inspiration profonde, puis une apnée","Par une apnée prolongée, poumons pleins"],"r":0,"e":"On évalue ainsi l'efficacité de la toux.","s":3},{"q":"Que traduit un PCF inférieur à 160 L/min ?","o":["Un risque de trachéotomie","Un risque de rétention de sécrétions","Une toux efficace","Une toux normale"],"r":0,"e":"Entre 160 et 270 L/min, il existe un risque de rétention de sécrétions.","s":3},{"q":"À partir de quelle valeur la toux est-elle considérée comme efficace ?","o":["PCF > 270 L/min","PCF > 160 L/min","PCF > 100 L/min","PCF > 400 L/min"],"r":0,"e":"Entre 160 et 270 L/min, il y a un risque de rétention de sécrétions.","s":3},{"q":"Combien de mesures de PCF réalise-t-on ?","o":["3, en retenant le meilleur résultat","1 seule, la première étant la plus fiable","5, en faisant la moyenne des valeurs","2, en retenant la plus faible des deux"],"r":0,"e":"On compare le débit obtenu à la valeur de référence.","s":3},{"q":"Que doit faire le patient avant de tousser dans le peak flow meter ?","o":["Expirer jusqu'au bout du VRE, puis inspirer jusqu'à la CPT","Inspirer jusqu'à la CPT, puis faire une pause de 10 s","Expirer normalement, puis inspirer jusqu'au VRI","Tousser trois fois pour libérer les voies aériennes"],"r":0,"e":"Il place ensuite l'embout en serrant les lèvres pour éviter les fuites.","s":3},{"q":"Quelle est une contre-indication de la mesure au peak flow meter ?","o":["Un décollement de rétine","Une bronchectasie","Une BPCO stable","Une toux productive"],"r":0,"e":"On retient aussi l'hémoptysie, l'angor récent, la crise hypertensive, l'œdème pulmonaire et l'anévrisme de l'aorte thoracique.","s":3},{"q":"Quelle est une contre-indication de la toux ?","o":["Un pneumothorax","Une hyperinsufflation","Une hypersécrétion bronchique","Une atélectasie"],"r":0,"e":"On retient aussi la fracture de côtes, le traumatisme crânien et la hernie abdominale.","s":3},{"q":"Quelle structure faut-il contracter simultanément lors de la toux dirigée ?","o":["Le plancher pelvien","Le diaphragme seul","Les scalènes","Les rhomboïdes"],"r":0,"e":"La toux dirigée se réalise en position assise après une inspiration lente et profonde suivie d'une pause.","s":3},{"q":"Combien de fois tousse-t-on lors de la toux dirigée ?","o":["2 ou 3 fois, bouche ouverte, sans inspirer entre","1 seule fois, bouche fermée, après une apnée","5 fois, bouche ouverte, en inspirant entre chaque","En continu, bouche fermée, pendant 10 secondes"],"r":0,"e":"On termine en respirant posément pour récupérer.","s":3},{"q":"De combien la toux assistée manuellement augmente-t-elle le PCF ?","o":["De 20 à 30 %","De 5 à 10 %","De 50 à 60 %","Elle ne le modifie pas"],"r":0,"e":"Elle doit être précédée d'une inspiration profonde.","s":3},{"q":"Quels sont les modes de placement des mains pour la toux assistée ?","o":["Thrust thoracique, thrust abdominal et thrust mixte","Thrust thoracique seul, mains sur le sternum","Thrust abdominal seul, mains sous l'ombilic","Thrust cervical, thrust lombaire et thrust pelvien"],"r":0,"e":"La compression s'exerce pendant l'expiration.","s":3},{"q":"Quelle est la particularité de l'AFE ou huffing ?","o":["Ce sont des expirations forcées à glotte ouverte","Ce sont des expirations forcées à glotte fermée","Ce sont des inspirations lentes à glotte ouverte","C'est une technique passive faite par le kiné"],"r":0,"e":"Elle se présente comme une alternative à la toux, avec de moindres pressions pulmonaires.","s":3},{"q":"Quel est l'avantage principal de l'AFE par rapport à la toux ?","o":["Elle mobilise les sécrétions sans collapsus bronchique","Elle va plus vite et demande moins de séances","Elle ne demande aucune collaboration du patient","Elle reste indolore chez tous les patients opérés"],"r":0,"e":"Elle déclenche de moindres pressions pulmonaires.","s":3},{"q":"Quel type de flux mobilise les sécrétions distales en AFE ?","o":["Un flux à bas débit et bas volume pulmonaire","Un flux à haut débit et haut volume pulmonaire","Un flux à haut débit et bas volume pulmonaire","Un flux constant, quel que soit le volume"],"r":0,"e":"Le flux à haut débit et haut volume élimine les sécrétions trachéales et bronchiques proximales.","s":3},{"q":"En quoi consiste la FET ?","o":["Des expirations forcées glotte ouverte, puis un contrôle respiratoire","Des expirations forcées glotte ouverte, enchaînées sans aucune pause","Un contrôle respiratoire seul, à volume courant","Des inspirations lentes en décubitus latéral, puis une toux"],"r":0,"e":"Elle n'est pas validée scientifiquement en termes d'efficacité.","s":3},{"q":"Quels débits progressifs peut-on viser au peak flow meter lors de la FET ?","o":["25 %, 50 %, 75 % puis 100 % du DEP","10 %, 20 %, 30 % puis 40 % du DEP","50 % puis 100 % du DEP seulement","100 % du DEP, dès la première expiration"],"r":0,"e":"L'expiration doit être forcée mais non violente.","s":3},{"q":"Quelles sont les trois phases de l'ACBT ?","o":["Contrôle respiratoire, expansion thoracique, expiration forcée","Aérosol, pression expiratoire positive, toux dirigée","Fluidification, progression, expulsion des sécrétions","Inspiration lente, apnée inspiratoire, expiration freinée"],"r":0,"e":"Ses objectifs sont la fluidification et la mobilisation des sécrétions. Sigles anglais : BC, TEE et FET.","s":3},{"q":"Quel est le rôle de la phase de contrôle respiratoire dans l'ACBT ?","o":["Elle alterne avec les autres phases et prévient le bronchospasme","Elle mobilise les sécrétions proximales par des toux successives","Elle mesure le débit expiratoire au peak flow meter","Elle remplace la FET chez les patients trop fatigués pour souffler"],"r":0,"e":"Il s'agit d'une ventilation abdomino-diaphragmatique à volume courant.","s":3},{"q":"Que comprennent les exercices d'expansion thoracique de l'ACBT ?","o":["Des inspirations lentes et profondes avec pause, ± vibrations","Des expirations forcées répétées à glotte ouverte, ± compressions","Des apnées expiratoires prolongées, ± percussions","Des toux dirigées successives, ± thrust abdominal"],"r":0,"e":"C'est la 2ᵉ phase de l'ACBT.","s":3},{"q":"Quelle est la durée recommandée de l'ACBT ?","o":["15 à 30 min, plusieurs fois par jour","5 min, une seule fois par jour","1 heure d'affilée, une fois par jour","2 min, avant chacun des repas"],"r":0,"e":"Référence : Pryor et Webber, 1993.","s":3},{"q":"Dans quelle position se réalise l'EDIC ?","o":["En décubitus latéral, région à traiter en haut","En décubitus latéral, région à traiter en bas","En décubitus dorsal, bras le long du corps","Assis, tronc droit et dos bien appuyé"],"r":0,"e":"Il tire parti de l'hyperinsufflation relative du poumon supra-latéral. La région à traiter est donc en supra-latéral.","s":3},{"q":"Qu'est-ce qui distingue l'EDIC de la spirométrie incitative ?","o":["Sa sélectivité pour la région à traiter","Sa durée de séance plus courte","L'absence d'apnée en fin d'inspiration","Le fait qu'aucune collaboration ne soit requise"],"r":0,"e":"Bien que technique de désobstruction, l'EDIC est essentiellement une technique d'expansion pulmonaire.","s":3},{"q":"Quelle est une contre-indication de l'EDIC ?","o":["Le post-opératoire immédiat d'une pneumonectomie","Une pneumonie localisée au lobe inférieur","Des atélectasies localisées de la base","Des bruits respiratoires bronchiques localisés"],"r":0,"e":"On retient aussi le manque de collaboration, la douleur et l'hyperréactivité bronchique.","s":3},{"q":"Quelle est la taille idéale des particules en aérosolthérapie ?","o":["Entre 1 et 5 micromètres","Entre 10 et 20 micromètres","Entre 0,01 et 0,1 micromètre","Entre 50 et 100 micromètres"],"r":0,"e":"La durée est de 10 min pour administrer un médicament et de plus de 15 min pour la fluidification.","s":3},{"q":"Quel dispositif de PEP ne permet pas de varier la position corporelle ?","o":["Le Flutter","Le cornet","L'Acapella","Le Thera-PEP"],"r":0,"e":"Il s'utilise avec une inclinaison de 45°, patient assis pieds en appui. Son nom complet est Flutter VRP1.","s":3},{"q":"Quelles sont les quatre étapes séquentielles de la désobstruction bronchique ?","o":["Fluidification","Décollement et mobilisation","Progression","Expulsion","Humidification"],"r":[0,1,2,3],"e":"Ces quatre étapes sont séquentielles et interdépendantes.","s":3},{"q":"De quoi dépend la sélection des stratégies de désobstruction ?","o":["Des résultats de l'évaluation","De la collaboration du patient","De la localisation des sécrétions dans l'arbre bronchique","De la rhéologie des sécrétions","De la dépense énergétique associée à la technique","Du coût du matériel disponible"],"r":[0,1,2,3,4],"e":"S'y ajoutent les autres facteurs d'obstruction associés à la stase bronchique, les comorbidités et l'âge.","s":3},{"q":"Quelles techniques concernent les voies aériennes extra-thoraciques ?","o":["Renifler et se moucher","Rire et pleurer chez l'enfant","Exercice physique et DRR chez l'enfant","Aspiration nasale ou buccale","ELTGOL en décubitus latéral"],"r":[0,1,2,3],"e":"Ces techniques d'expiration et d'inspiration forcées s'adressent aux voies aériennes extra-thoraciques.","s":3},{"q":"Quelles sont les modalités de toux décrites ?","o":["Spontanée et dirigée","Provoquée chez l'enfant","Assistée manuellement","Assistée mécaniquement","La toux réflexe nocturne"],"r":[0,1,2,3],"e":"À ces modalités s'ajoutent l'AFE (huffing), la FET et l'aspiration.","s":3},{"q":"Comment simule-t-on la toux lors de la mesure du Peak Cough Flow ?","o":["Par une expiration forcée, glotte d'abord fermée","Par une expiration lente et complète, glotte ouverte","Par une inspiration profonde et rapide","Par une apnée tenue à poumons pleins, puis un soupir"],"r":0,"e":"L'expiration forcée avec fermeture de la glotte simule la toux ; les patients à toux inefficace présentent une faiblesse des muscles respiratoires.","s":3},{"q":"Quelles sont les étapes de la mesure du Peak Cough Flow ?","o":["Expirer jusqu'au bout du volume de réserve expiratoire","Inspirer jusqu'à la capacité pulmonaire totale","Tousser rapidement sans prolonger l'expiration","Répéter deux fois et consigner le meilleur des trois","Réaliser trois cycles respiratoires calmes avant la mesure"],"r":[0,1,2,3],"e":"Il faut aussi tenir le dispositif sans gêner le curseur et serrer les lèvres autour de l'embout pour éviter les fuites.","s":3},{"q":"Quelles sont les contre-indications de la mesure du peak flow ?","o":["Hémoptysie et angor récent","Décollement de rétine, crise hypertensive","Œdème pulmonaire","Anévrisme de l'aorte thoracique","Fracture de côtes récente"],"r":[0,1,2,3],"e":"La fracture de côtes, comme le pneumothorax, le traumatisme crânien et la hernie abdominale, est une contre-indication de la toux elle-même.","s":3},{"q":"Quelles sont les étapes de la toux dirigée ?","o":["Inspiration lente et profonde à haut volume","Pause inspiratoire","Tousser 2 ou 3 fois bouche ouverte","Contracter le plancher pelvien en même temps","Respirer posément pour récupérer","Expirer à lèvres pincées avant de tousser"],"r":[0,1,2,3,4],"e":"Les cinq étapes se réalisent en position assise. Pendant la toux, on n'inspire pas entre les efforts.","s":3},{"q":"Quels placements de mains sont décrits pour la toux assistée manuellement ?","o":["Thrust thoracique","Thrust abdominal","Thrust mixte, thorax et abdomen","Thrust cervical"],"r":[0,1,2],"e":"Trois placements, la technique devant être précédée d'une inspiration profonde et augmentant le PCF de 20 à 30 %.","s":3},{"q":"Quel est l'avantage de l'AFE par rapport à la toux ?","o":["Elle déclenche de moindres pressions pulmonaires","Elle mobilise sans collapsus des voies aériennes","Elle se fait à glotte fermée, comme la toux","Elle ne nécessite aucune coopération du patient"],"r":[0,1],"e":"L'AFE ou huffing se fait à glotte ouverte : moindres pressions et pas de collapsus, ce qui en fait une alternative à la toux.","s":3},{"q":"Quels débits vise-t-on progressivement avec un peak flow meter lors de la FET ?","o":["25 %, 50 %, 75 % puis 100 % du DEP","10 %, 20 % puis 30 % du DEP","100 % du DEP, à chaque expiration","50 % du DEP, puis jamais davantage"],"r":0,"e":"La FET peut se guider au peak flow meter en visant 25, 50, 75 puis 100 % du DEP. L'expiration doit être forcée mais non violente.","s":3},{"q":"Quel est le statut scientifique de la FET ?","o":["Elle n'est pas validée scientifiquement","Elle est validée par plusieurs essais randomisés","Elle est contre-indiquée chez l'adulte","Elle est le traitement de référence actuel"],"r":0,"e":"La fiche précise que la FET n'est pas validée scientifiquement en termes d'efficacité.","s":3},{"q":"Que comprend la phase TEE du cycle actif des techniques respiratoires ?","o":["Des inspirations lentes et profondes","Une pause inspiratoire","Avec ou sans percussion et vibration","Une ventilation à volume courant"],"r":[0,1,2],"e":"TEE : inspirations lentes et profondes avec pause inspiratoire, avec ou sans percussion et vibration. La ventilation à volume courant caractérise la phase BC.","s":3},{"q":"Quel est le rôle de la phase BC dans l'ACBT ?","o":["Ventiler à volume courant, au diaphragme","Alterner avec les autres phases","Prévenir le bronchospasme","Expulser les sécrétions proximales"],"r":[0,1,2],"e":"Le Breathing Control alterne avec les autres phases et prévient le bronchospasme. L'expulsion relève de la FET.","s":3},{"q":"Sur quel mécanisme l'EDIC repose-t-il ?","o":["L'expansion régionale passive des voies périphériques","L'hyperinsufflation relative du poumon supra-latéral","L'augmentation du diamètre transversal du thorax","La compression active du poumon infra-latéral"],"r":[0,1,2],"e":"L'EDIC tire parti de l'expansion régionale passive obtenue par l'hyperinsufflation relative du poumon supra-latéral et l'augmentation du diamètre transversal.","s":3},{"q":"Vers quelle zone le décubitus antéro-latéral dirige-t-il la ventilation en EDIC ?","o":["La zone postéro-basale du poumon supra-latéral","La face antéro-basale du poumon supra-latéral","Les sommets des deux poumons, en même temps","La zone postéro-basale du poumon infra-latéral"],"r":0,"e":"Décubitus antéro-latéral → zone postéro-basale du poumon supra-latéral. Décubitus postéro-latéral → face antéro-basale.","s":3},{"q":"Quelles sont les contre-indications de l'EDIC ?","o":["Manque de collaboration","Douleur importante","Hyperréactivité bronchique","Pneumonectomie récente","Pneumonie localisée"],"r":[0,1,2,3],"e":"Les quatre premières sont des contre-indications. La pneumonie et les atélectasies localisées sont au contraire des indications. La pneumonectomie compte au post-opératoire immédiat.","s":3},{"q":"Quels sont les objectifs de l'aérosolthérapie ?","o":["Fluidifier les sécrétions pour les mobiliser","Maintenir le transport mucociliaire","Administrer des médicaments inhalés","Mesurer le débit expiratoire de pointe"],"r":[0,1,2],"e":"Trois objectifs, l'appareil transformant les liquides en particules d'aérosol par compresseur mécanique ou ultrasonique. Médicaments : bronchodilatateurs, anti-inflammatoires, mucolytiques.","s":3},{"q":"Quelle est la taille idéale des particules d'aérosol ?","o":["Entre 1 et 5 µm","Entre 10 et 20 µm","Entre 0,1 et 0,5 µm","Plus de 50 µm"],"r":0,"e":"La taille idéale se situe entre 1 et 5 µm ; l'efficacité dépend aussi du schéma ventilatoire et de la durée.","s":3},{"q":"Quelles durées d'aérosolthérapie sont recommandées ?","o":["10 minutes pour un médicament","Plus de 15 minutes pour fluidifier","30 minutes dans tous les cas","5 minutes, quel que soit le but"],"r":[0,1],"e":"10 min pour l'administration d'un médicament, plus de 15 min lorsque l'objectif est la fluidification.","s":3},{"q":"Que mesure l'épreuve fonctionnelle respiratoire ?","o":["Le volume inspiré ou expiré en fonction du temps","La saturation en oxygène pendant l'effort","La pression artérielle dans l'artère pulmonaire","La force de contraction du diaphragme"],"r":0,"e":"On peut mesurer le volume ou le débit, par des manœuvres lentes ou forcées.","s":4},{"q":"Quelles sont les principales mesures de la spirométrie ?","o":["CVF, VEMS, VEMS/CVF et DEP","PIM, PEM, CRF et VR","SpO₂, PaO₂, PaCO₂ et pH","FC, PA, FR et SpO₂"],"r":0,"e":"L'affichage se fait sous forme de courbe débit-volume et de courbe volume-temps.","s":4},{"q":"Pourquoi mesure-t-on le poids et la taille le jour du test ?","o":["Ce sont des déterminants de la taille pulmonaire","Ils servent à doser le bronchodilatateur","Ils servent à choisir la taille de l'embout","Ils permettent d'estimer le seuil de douleur"],"r":0,"e":"On vérifie aussi les prothèses et on recueille signes et symptômes.","s":4},{"q":"Combien de temps doit durer l'expiration forcée ?","o":["Au moins 6 secondes","Au moins 2 secondes","Au moins 15 secondes","Au moins 1 seconde"],"r":0,"e":"Le temps expiratoire forcé peut aller jusqu'à 15 s ; la pause inspiratoire doit être ≤ 2 s.","s":4},{"q":"Quelle est la durée maximale de la pause après l'inspiration maximale ?","o":["2 secondes, idéalement sans pause","6 secondes, idéalement sans pause","10 secondes, le temps de se préparer","15 secondes, pour remplir les alvéoles"],"r":0,"e":"La consigne est ensuite d'expirer vite et fort, glotte ouverte.","s":4},{"q":"Combien de mesures réalise-t-on lors d'une EFR ?","o":["3 à 8, dont au moins 3 acceptables et reproductibles","1 seule, si elle est jugée acceptable","Exactement 5, dont au moins 2 acceptables et reproductibles","Au moins 10, dont la moitié reproductibles"],"r":0,"e":"Une mesure acceptable présente un DEP, ≥ 6 s de temps expiratoire, une faible fuite et aucun artefact.","s":4},{"q":"Quels sont les critères d'une mesure acceptable ?","o":["DEP net, au moins 6 s d'expiration, faible fuite, pas d'artefact","Au moins 2 s d'expiration, fuite tolérée, toux acceptée","VEMS au-delà de 80 %, sans aucune pause inspiratoire","Pas de bronchodilatateur pris, pas de fuite, 3 s d'expiration"],"r":0,"e":"La toux est un exemple d'artefact rendant la mesure inacceptable.","s":4},{"q":"Quel écart maximal définit la reproductibilité pour le VEMS et la CVF ?","o":["Moins de 150 mL","Moins de 500 mL","Moins de 50 mL","Moins de 1 L"],"r":0,"e":"Il faut 3 mesures acceptables remplissant ce critère.","s":4},{"q":"Quel paramètre permet d'identifier une obstruction ?","o":["Le rapport VEMS/CVF","La CVF seule","Le DEP seul","La capacité résiduelle fonctionnelle"],"r":0,"e":"La CVF avant et après BD permet d'identifier une restriction.","s":4},{"q":"Quel paramètre permet d'identifier une restriction ?","o":["La CVF avant et après bronchodilatateur","Le rapport VEMS/CVF avant bronchodilatateur","Le DEP mesuré après bronchodilatateur","Le volume courant au repos, sans bronchodilatateur"],"r":0,"e":"Le VEMS après BD permet d'apprécier le degré d'obstruction.","s":4},{"q":"Comment se calcule la réponse au bronchodilatateur ?","o":["(VEMS post − VEMS pré) × 100 / valeur prédite","(VEMS post − VEMS pré) × 100 / CVF mesurée","(VEMS post / VEMS pré) × 100 / valeur prédite","(CVF post − CVF pré) × 100 / VEMS mesuré"],"r":0,"e":"Une valeur supérieure à 10 % signe une réversibilité significative de l'obstruction. La valeur prédite tient compte du sexe et de l'âge ; pré et post désignent avant et après bronchodilatateur.","s":4},{"q":"À partir de quel seuil la réversibilité de l'obstruction est-elle significative ?","o":["Plus de 10 %","Plus de 5 %","Plus de 25 %","Plus de 50 %"],"r":0,"e":"On choisit un BD de courte ou longue durée d'action, avec dose et mode d'administration adaptés.","s":4},{"q":"Quelle est la première étape de l'interprétation d'une EFR ?","o":["Évaluer la qualité et la forme des courbes","Calculer d'emblée la réversibilité au BD","Identifier la CVF pour classer le trouble","Mesurer le DEP et le comparer à la norme"],"r":0,"e":"Il faut au minimum 3 courbes acceptables et reproductibles, jusqu'à 8 mesures. Ensuite seulement : rapport VEMS/CVF, CVF, puis VEMS après BD.","s":4},{"q":"Quelles données saisit-on pour créer un nouveau patient sur le spiromètre ?","o":["Naissance, poids, taille, sexe biologique, origine ethnique","Nom, prénom, adresse, médecin traitant, mutuelle","Numéro de sécurité sociale, groupe sanguin, allergies","Traitement en cours, tabagisme, profession, antécédents"],"r":0,"e":"On accède au menu par « #ID » puis « NEW ».","s":4},{"q":"Quelles touches permettent de revoir les valeurs numériques sur le Spirobank II ?","o":["« DATA » puis « SPIRO »","« NEW » puis « ID »","« MENU » puis « SET »","« ON » puis « OFF »"],"r":0,"e":"Les courbes débit/volume et volume/temps s'affichent en premier.","s":4},{"q":"Que peut afficher un moniteur multiparamétrique ?","o":["Pressions, oxygénation, respiration, température, ECG","Pressions, glycémie capillaire, diurèse, température, ECG","Oxygénation seule, avec la courbe de pouls","Pression artérielle seule, en mesure continue"],"r":0,"e":"Le monitorage peut se faire au repos et/ou à l'exercice.","s":4},{"q":"Comment prépare-t-on le patient pour un ECG ?","o":["Torse nu, en décubitus dorsal, peau rasée et nettoyée","Assis, habillé, électrodes posées sur le vêtement","Debout, torse nu, sans aucune préparation cutanée","En décubitus ventral, peau humidifiée à l'eau"],"r":0,"e":"Les électrodes peuvent être jetables ou réutilisables.","s":4},{"q":"Où se place l'électrode V1 ?","o":["4ᵉ espace intercostal droit, bord sternal","4ᵉ espace intercostal gauche, bord sternal","5ᵉ espace intercostal gauche, médio-claviculaire","5ᵉ espace intercostal gauche, axillaire moyenne"],"r":0,"e":"V2 se place au 4ᵉ espace intercostal gauche, bord sternal.","s":4},{"q":"Où se place l'électrode V4 ?","o":["5ᵉ espace intercostal gauche, ligne médio-claviculaire","4ᵉ espace intercostal gauche, au bord du sternum","5ᵉ espace intercostal gauche, ligne axillaire antérieure","Au milieu de la ligne qui joint V2 et V4"],"r":0,"e":"V3 se place au milieu entre V2 et V4.","s":4},{"q":"Comment détermine-t-on la position de V3 ?","o":["Au milieu entre V2 et V4","Au milieu entre V1 et V2","Au milieu entre V4 et V5","Au 4ᵉ espace intercostal droit"],"r":0,"e":"V4 se situe au 5ᵉ EIC gauche sur la ligne médio-claviculaire.","s":4},{"q":"Où se place V5 ?","o":["5ᵉ espace intercostal gauche, ligne axillaire antérieure","5ᵉ espace intercostal gauche, ligne axillaire moyenne","4ᵉ espace intercostal gauche","Ligne médio-claviculaire droite"],"r":0,"e":"V6 se place sur la ligne axillaire moyenne.","s":4},{"q":"Où se place V6 ?","o":["5ᵉ espace intercostal gauche, ligne axillaire moyenne","5ᵉ espace intercostal gauche, ligne axillaire antérieure","4ᵉ espace intercostal droit","Ligne médio-claviculaire gauche"],"r":0,"e":"V5 se place sur la ligne axillaire antérieure.","s":4},{"q":"Combien d'électrodes sont fixes pour le monitorage des dérivations précordiales ?","o":["4","5","6","3"],"r":0,"e":"Pour les dérivations périphériques, 5 électrodes sont fixes (membres + V1).","s":4},{"q":"Combien d'électrodes sont fixes pour le monitorage des dérivations périphériques ?","o":["5","4","6","2"],"r":0,"e":"Les électrodes sont maintenues aux membres et en V1, et l'on modifie le moniteur cardiaque.","s":4},{"q":"Sur quelle dérivation règle-t-on le moniteur pour le monitorage à l'exercice ?","o":["DII","DI","V1","aVR"],"r":0,"e":"Les électrodes des membres sont ensuite transférées vers le thorax.","s":4},{"q":"À quel membre correspond l'électrode rouge au repos ?","o":["Le bras droit","Le bras gauche","La jambe droite","La jambe gauche"],"r":0,"e":"Jaune = bras gauche, noir = jambe droite, vert = jambe gauche, bleu = précordiales.","s":4},{"q":"Où se place l'électrode rouge lors du monitorage à l'exercice ?","o":["Sous l'extrémité sternale de la clavicule droite","Au même endroit que V6, sur la ligne axillaire","Sur l'hémithorax droit, en bas du gril costal","Au même endroit que V5, à gauche"],"r":0,"e":"Jaune se place au niveau de V6, verte au niveau de V5, bleue au niveau de V2 et noire sur l'hémithorax droit.","s":4},{"q":"Où se place l'électrode jaune à l'exercice ?","o":["Au même endroit que V6","Au même endroit que V5","Au même endroit que V2","Sur l'hémithorax droit"],"r":0,"e":"L'électrode verte se place au niveau de V5.","s":4},{"q":"Quelle précaution de sécurité est mentionnée dans les procédures finales ?","o":["Vérifier le sélecteur de tension 110/220","Débrancher le patient avant l'allumage","Utiliser 4 électrodes réutilisables seulement","Éteindre le moniteur pendant l'enregistrement"],"r":0,"e":"On connecte ensuite le câble-patient au moniteur puis aux électrodes selon le code couleur.","s":4},{"q":"Quelles phases de la séance observe-t-on lors de la pratique ECG à l'exercice ?","o":["Échauffement, conditionnement, récupération","Repos, effort maximal, sommeil réparateur","Inspiration, apnée, expiration forcée","Préparation, action, correction posturale"],"r":0,"e":"On associe signes et symptômes : Borg, FC, SatO₂ et PA.","s":4},{"q":"Quelles sont les quatre étapes de la procédure de l'EFR ?","o":["Quelques respirations tranquilles","Inspiration maximale avec pause ≤ 2 s","Expirer fort et vite à glotte ouverte, ≥ 6 secondes","Respirer tranquillement","Réaliser une apnée de cinq secondes en fin d'expiration"],"r":[0,1,2,3],"e":"L'idéal est même de ne pas faire de pause après l'inspiration maximale.","s":4},{"q":"Quelles consignes verbales accompagnent l'expiration forcée ?","o":["« Expirez vite et fort »","« Continuez, même si l'air ne sort plus »","« Retenez votre souffle quelques secondes »","« Inspirez lentement par le nez »"],"r":[0,1],"e":"Ces deux consignes soutiennent l'effort expiratoire jusqu'au plateau de la courbe volume-temps.","s":4},{"q":"Quels critères définissent une mesure acceptable ?","o":["Un débit expiratoire de pointe net","Au moins 6 secondes d'expiration","Une faible fuite d'air","Pas d'artefact comme la toux","Moins de 150 mL d'écart entre essais"],"r":[0,1,2,3],"e":"Ces quatre critères définissent l'acceptabilité d'une mesure.","s":4},{"q":"À quelle étape identifie-t-on le degré d'obstruction ?","o":["En identifiant le VEMS après bronchodilatateur","En identifiant le VEMS/CVF avant bronchodilatateur","En identifiant la CVF avant et après bronchodilatateur","En évaluant la qualité et la forme des courbes"],"r":0,"e":"Étape 4 : identifier le VEMS après BD pour établir le degré d'obstruction. Le VEMS/CVF (étape 2) dit s'il y a obstruction, la CVF (étape 3) s'il y a restriction.","s":4},{"q":"Quelles références encadrent l'EFR dans ce cours pratique ?","o":["Miller MR. et al., Eur Respir J 2005","Graham BL. et al., Am J Respir Crit Care Med 2019","Stanojevic S. et al., Eur Respir J 2022","GOLD COPD report 2025","Postiaux G., Kinésithérapie respiratoire, 2004"],"r":[0,1,2,3],"e":"S'y ajoute Pellegrino R. et al., Eur Respir J 2005.","s":4},{"q":"Comment monte-t-on le Spirobank II ?","o":["Embout dans la turbine, puis turbine dans le spiromètre","Turbine dans l'embout, puis embout dans le spiromètre","Embout directement dans le spiromètre, sans turbine","Capteur de débit sur l'embout, puis câble au spiromètre"],"r":0,"e":"L'embout buccal se place dans la turbine, puis la turbine dans le spiromètre.","s":4},{"q":"Qu'affiche le premier écran du Spirobank II à l'allumage ?","o":["La référence du fabricant, l'heure et la date","Le menu de service, l'heure et la date","Les dernières courbes, l'heure et la date","Les données du patient, l'heure et la date"],"r":0,"e":"Le premier écran donne référence du fabricant, heure et date ; le second donne accès au menu de service.","s":4},{"q":"Quelles données saisit-on pour créer un nouveau patient ?","o":["Date de naissance","Poids en kg et taille en cm","Sexe biologique","Origine ethnique","Numéro de dossier"],"r":[0,1,2,3],"e":"Ces données déterminent les valeurs prédites auxquelles on comparera les mesures.","s":4},{"q":"Qu'affiche le moniteur multiparamétrique ?","o":["PAS, PAD et PAM","Oxygénation sanguine","Activité respiratoire et température","Activité électrique du cœur","Glycémie capillaire en continu"],"r":[0,1,2,3],"e":"Le moniteur multiparamétrique affiche l'ensemble de ces paramètres.","s":4},{"q":"Combien d'électrodes restent fixes pour le monitorage des dérivations précordiales, et sur quoi règle-t-on le moniteur ?","o":["4 fixes aux membres, moniteur réglé sur V","5 fixes aux membres, moniteur réglé sur DII","4 fixes au thorax, moniteur réglé sur DI","6 fixes au thorax, moniteur réglé sur V6"],"r":0,"e":"Précordiales : on maintient les 4 électrodes des membres, on règle sur V et on déplace l'électrode pour obtenir V1 à V6.","s":4},{"q":"Quelles dérivations obtient-on avec le montage à 5 électrodes fixes ?","o":["DI, DII et DIII","aVR, aVL et aVF","V1, V2 et V3","V4, V5 et V6"],"r":[0,1],"e":"Avec les électrodes des membres et V1 fixes (5 fixes), on modifie le moniteur pour obtenir DI, DII, DIII, aVR, aVL et aVF.","s":4},{"q":"Où se place l'électrode jaune lors du monitorage à l'exercice ?","o":["Au même endroit que V6","Au même endroit que V5","Sur l'hémithorax droit","Sous l'extrémité sternale de la clavicule droite"],"r":0,"e":"À l'exercice : rouge sous l'extrémité sternale de la clavicule droite, jaune en V6, noire sur l'hémithorax droit, verte en V5, bleue en V2.","s":4},{"q":"Où se place l'électrode verte lors du monitorage à l'exercice ?","o":["Au même endroit que V5","Au même endroit que V6","Au même endroit que V2","Sur la jambe gauche"],"r":0,"e":"L'électrode verte, qui est à la jambe gauche au repos, se place en V5 à l'exercice.","s":4},{"q":"Où se place l'électrode bleue à l'exercice ?","o":["Au même endroit que V2","Au même endroit que V5","Sur l'hémithorax droit","Sur le bras gauche"],"r":0,"e":"L'électrode bleue, précordiale au repos, se place au même endroit que V2 à l'exercice.","s":4},{"q":"Quelles procédures finales précèdent l'enregistrement ?","o":["Vérifier le sélecteur de tension 110/220","Connecter câble et électrodes selon le code couleur","Allumer ensuite l'appareil","Régler la vitesse de défilement à 50 mm/s"],"r":[0,1,2],"e":"Sécurité, connexions selon le code couleur, puis allumage.","s":4},{"q":"Quels enregistrements pratiques sont proposés en positions différentes ?","o":["En décubitus dorsal","Assis","Debout","En décubitus ventral"],"r":[0,1,2],"e":"Trois positions sont proposées, permettant notamment d'observer l'arythmie sinusale respiratoire.","s":4},{"q":"Quels signes et symptômes associe-t-on à l'ECG lors de l'exercice pratique ?","o":["L'échelle de Borg","La fréquence cardiaque","La saturation en oxygène","La pression artérielle","La pression intracrânienne"],"r":[0,1,2,3],"e":"Ces quatre paramètres sont associés à l'observation ECG au cours des phases d'échauffement, de conditionnement et de récupération.","s":4},{"q":"Quel rapport permet d'identifier une obstruction à l'EFR ?","o":["Le rapport VEMS/CVF","La CVF mesurée seule","Le DEP mesuré seul","Le VEMS mesuré seul"],"r":0,"e":"Le rapport VEMS/CVF identifie l'obstruction ; la CVF oriente vers la restriction et le VEMS après BD précise le degré d'obstruction.","s":4},{"q":"Quel est le nombre de mesures autorisé lors d'une EFR ?","o":["De 3 à 8","Exactement 3","Au moins 10","Une seule suffit"],"r":0,"e":"On réalise 3 à 8 mesures, avec un minimum de 3 acceptables et reproductibles.","s":4},{"q":"Sur quelles courbes l'affichage de l'EFR se fait-il ?","o":["La courbe débit-volume","La courbe volume-temps","La courbe pression-volume","La courbe débit-pression"],"r":[0,1],"e":"Deux affichages : courbe débit-volume et courbe volume-temps.","s":4},{"q":"Quel est l'ordre des étapes de l'examen objectif ?","o":["Aspect général, signes vitaux, inspection, palpation, percussion, auscultation","Inspection, signes vitaux, auscultation, palpation, percussion, aspect général","Signes vitaux, aspect général, palpation, inspection, auscultation, percussion","Aspect général, inspection, auscultation, signes vitaux, percussion, palpation"],"r":0,"e":"Viennent ensuite les autres tests et les examens complémentaires de diagnostic.","s":5},{"q":"Que signifie la fiabilité d'un instrument de mesure ?","o":["La réduction de l'erreur, quels que soient le moment et l'examinateur","La capacité à mesurer ce qu'il prétend mesurer, sans biais","La capacité à détecter des changements cliniquement importants","La rapidité d'exécution, quel que soit l'examinateur"],"r":0,"e":"La validité est la capacité à mesurer ce qu'on prétend mesurer, la sensibilité celle de détecter un changement.","s":5},{"q":"Pourquoi faut-il interpréter avec précaution la palpation, la percussion et l'auscultation ?","o":["Ils dépendent des sens de l'examinateur et sont peu fiables","Ils coûtent cher et demandent un matériel spécifique","Ils sont douloureux et souvent mal tolérés par le patient","Ils sont interdits aux kinés sans prescription médicale"],"r":0,"e":"Il faut privilégier autant que possible des tests et instruments validés et de bonne fiabilité. Leur fiabilité est très faible, car ils reposent aussi sur l'habileté manuelle.","s":5},{"q":"Quelle est la fréquence respiratoire normale chez l'adulte ?","o":["12-20 cpm","60-80 cpm","20-30 cpm","5-10 cpm"],"r":0,"e":"La fréquence cardiaque normale est de 60-80 bpm.","s":5},{"q":"Quelle est la température corporelle de référence ?","o":["36 à 37 °C","35 à 36 °C","37 à 38 °C","38 à 39 °C"],"r":0,"e":"La pression artérielle de référence est de 120/80 mmHg.","s":5},{"q":"Quelles régions peuvent présenter un tirage ?","o":["Sus-claviculaire, sus-sternale, intercostale, sous-costale","Intercostale seule, en regard des deux bases pulmonaires","Abdominale seule, sous l'ombilic et sur les flancs","Sus-sternale seule, au creux jugulaire du cou"],"r":0,"e":"Le tirage est la dépression inspiratoire de ces régions.","s":5},{"q":"Que traduit une cyanose centrale ?","o":["Une hypoxémie","Une hypercapnie isolée","Une insuffisance cardiaque droite","Une déshydratation"],"r":0,"e":"C'est un signe objectif de difficulté respiratoire.","s":5},{"q":"Quelle est la différence entre stridor et cornage ?","o":["Le cornage est plus grave et s'entend sans stéthoscope","Le stridor est plus grave et s'entend sans stéthoscope","Le cornage est plus aigu et ne s'entend qu'au stéthoscope","Ils sont identiques et se distinguent par leur durée"],"r":0,"e":"Le cornage indique une obstruction de la trachée supérieure, de la glotte ou du larynx.","s":5},{"q":"Que peut indiquer une turgescence jugulaire ?","o":["Une insuffisance cardiaque droite","Une hypoxémie artérielle sévère","Une hyperinsufflation thoracique","Un pneumothorax de faible abondance"],"r":0,"e":"Elle est recherchée lors de l'inspection du cou.","s":5},{"q":"Comment se manifeste l'hippocratisme digital ?","o":["Doigts en baguette de tambour, ongles en verre de montre","Doigts œdématiés et rouges, ongles cassants et striés","Ongles striés longitudinalement, pulpe aplatie","Doigts froids et blancs, ongles bleutés"],"r":0,"e":"Il s'observe à l'inspection des extrémités, avec la cyanose périphérique et les œdèmes.","s":5},{"q":"Que peuvent indiquer des œdèmes bilatéraux des membres inférieurs ?","o":["Une insuffisance cardiaque droite","Une hypoxémie centrale aiguë","Une obstruction bronchique diffuse","Une atélectasie du lobe inférieur"],"r":0,"e":"Ils sont recherchés lors de l'inspection des extrémités.","s":5},{"q":"Quelles sont les caractéristiques du thorax en tonneau ?","o":["3 diamètres augmentés, surtout l'antéro-postérieur","Diamètre antéro-postérieur diminué, sternum creusé","Seul le diamètre transversal augmenté, côtes verticales","Sternum déprimé, 3 diamètres diminués"],"r":0,"e":"Il s'associe à une horizontalisation des arcs costaux et un aplatissement des coupoles ; typique de la BPCO et de l'asthme. C'est l'effet de l'hyperinsufflation.","s":5},{"q":"Quelle déformation correspond à une diminution du diamètre AP dans le sens antérieur ?","o":["Le pectus excavatum","Le pectus carinatum","Le thorax en tonneau","Le thorax cyphotique"],"r":0,"e":"Il existe une dépression du sternum, plus inférieure, pouvant causer une restriction.","s":5},{"q":"Que caractérise le pectus carinatum ?","o":["Un sternum déplacé vers l'avant, diamètre AP antérieur accru","Un sternum déprimé, diamètre AP antérieur diminué","Un rachis déplacé vers l'arrière, diamètre AP postérieur accru","Une rotation vertébrale, avec gibbosité costale"],"r":0,"e":"Les cartilages adjacents au sternum bombé sont déprimés.","s":5},{"q":"Chez quels patients la déformation cyphoscoliotique est-elle fréquente ?","o":["Les patients neuromusculaires","Les patients BPCO","Les patients asthmatiques","Les patients obèses"],"r":0,"e":"La distorsion du poumon adjacent peut causer une restriction.","s":5},{"q":"Quel est le rapport inspiration/expiration normal ?","o":["1:2","2:1","1:1","1:3"],"r":0,"e":"C'est le rapport de l'eupnée, rythme doux et uniforme.","s":5},{"q":"Comment définit-on la tachypnée ?","o":["Une respiration rapide et superficielle","Une respiration lente et plus profonde","Une respiration plus profonde à fréquence normale","Un arrêt respiratoire de plus de 20 secondes"],"r":0,"e":"La bradypnée est une fréquence diminuée avec une respiration plus profonde.","s":5},{"q":"Qu'est-ce que la polypnée (ou hyperpnée) ?","o":["Une respiration plus profonde, à fréquence normale ou accrue","Une respiration rapide et superficielle, à rythme régulier","Une respiration régulière entrecoupée de longues apnées","Une inspiration profonde suivie d'une apnée prolongée"],"r":0,"e":"À distinguer de la tachypnée, rapide et superficielle. Le rythme reste régulier.","s":5},{"q":"Quel rythme se caractérise par une profondeur croissante puis décroissante entrecoupée d'apnées ?","o":["Cheyne-Stokes","Biot","Kussmaul","Apneustique"],"r":0,"e":"Il évoque des lésions cérébrales par hypoxie.","s":5},{"q":"À quoi correspond la respiration de Biot ?","o":["Une profondeur et une fréquence irrégulières : lésion bulbaire","Une respiration régulière et profonde : acidose métabolique","Une respiration rapide et superficielle : douleur pleurale","Une inspiration rapide, puis une expiration soudaine : coma"],"r":0,"e":"Elle est aussi appelée ataxique et de mauvais pronostic.","s":5},{"q":"Que caractérise la respiration de Kussmaul ?","o":["Inspiration rapide et profonde, pause, expiration soudaine, pause","Profondeur croissante puis décroissante, suivie d'une apnée","Apnées répétées, entrecoupées de quelques cycles irréguliers","Fréquence basse, inspiration profonde suivie d'une apnée"],"r":0,"e":"L'apneustique correspond à une fréquence basse avec inspiration profonde suivie d'une apnée, par lésion du tronc cérébral.","s":5},{"q":"Que palpe-t-on lors de l'examen de la peau en kinésithérapie respiratoire ?","o":["Température, sudation, texture, élasticité, cicatrices","Température, coloration, pilosité, ongles, cheveux","Pouls capillaire, pression artérielle, saturation, pouls","Cicatrices, tatouages, grains de beauté, pilosité"],"r":0,"e":"On palpe aussi le tonus des muscles accessoires, les points douloureux et les sensations tactiles anormales. On cherche aussi un emphysème sous-cutané.","s":5},{"q":"Que permet d'évaluer la palpation de la trachée ?","o":["La position du médiastin","Le tonus des muscles accessoires","La mobilité diaphragmatique","L'expansion des lobes"],"r":0,"e":"On recherche une déviation trachéale.","s":5},{"q":"Pourquoi fléchit-on légèrement le cou lors de la recherche d'une déviation trachéale ?","o":["Pour relâcher les muscles sterno-cléido-mastoïdiens","Pour dégager la clavicule du doigt qui palpe la trachée","Pour augmenter la pression intrathoracique","Pour faciliter la toux pendant la palpation"],"r":0,"e":"Le menton est ensuite positionné sur la ligne médiane et l'index placé dans l'incisure supra-sternale.","s":5},{"q":"Quel lobe explore la mobilité thoracique qualitative costale moyenne ?","o":["Le lobe moyen à droite et la lingula à gauche","Le lobe supérieur des deux côtés, face antérieure","Le lobe inférieur des deux côtés, face postérieure","Les deux bases, face latérale"],"r":0,"e":"La costale supérieure explore le lobe supérieur, la costale inférieure le lobe inférieur.","s":5},{"q":"Pour évaluer la mobilité costale inférieure, où se place le kinésithérapeute ?","o":["Face à la face postérieure du patient","Face à la face antérieure du patient","Latéralement au patient couché","Derrière la tête du patient"],"r":0,"e":"Les niveaux costal supérieur et moyen s'évaluent par la face antérieure.","s":5},{"q":"Quelle variation de périmètre est attendue au niveau du pli axillaire ?","o":["2-3 cm","4-5 cm","7-8 cm","10-12 cm"],"r":0,"e":"4-5 cm à l'appendice xiphoïde et 7-8 cm à la cicatrice ombilicale.","s":5},{"q":"Quelle variation de périmètre est attendue à la cicatrice ombilicale ?","o":["7-8 cm","2-3 cm","4-5 cm","1-2 cm"],"r":0,"e":"C'est le repère de la mobilité diaphragmatique en mesure quantitative.","s":5},{"q":"Dans quelle position s'évalue la mobilité diaphragmatique ?","o":["Décubitus dorsal, membres inférieurs fléchis, pieds en appui","Assis, pieds en appui, mains posées sur les cuisses","Debout, bras le long du corps, pieds écartés à la largeur du bassin","Décubitus ventral, membres inférieurs tendus"],"r":0,"e":"Cette position relâche la paroi abdominale.","s":5},{"q":"Où le kinésithérapeute place-t-il ses pouces pour évaluer la mobilité diaphragmatique ?","o":["Sur la ligne mamelonnaire, un de chaque côté","Sur l'appendice xiphoïde, l'un contre l'autre","Sur les crêtes iliaques, un de chaque côté","Sur les clavicules, au tiers moyen"],"r":0,"e":"Il évalue l'amplitude et la tension des deux hémidiaphragmes simultanément, en accompagnant toujours le mouvement.","s":5},{"q":"Quelles sont les trois qualités attendues d'un instrument de mesure ?","o":["La validité : mesurer ce qu'il prétend mesurer","La fiabilité : réduire la composante d'erreur","La sensibilité : détecter un changement important","La rapidité : se faire passer en peu de temps"],"r":[0,1,2],"e":"Validité, fiabilité et sensibilité sont les trois qualités définies.","s":5},{"q":"Quels états de conscience distingue-t-on à l'aspect général ?","o":["Vigile","Léthargie","Stupeur","Coma","Agitation"],"r":[0,1,2,3],"e":"Quatre états, à évaluer avec la coopération, l'orientation, l'impression générale et l'état nutritionnel.","s":5},{"q":"Quelles fonctions évalue-t-on dans l'aspect général ?","o":["Vision et audition","Mémoire ancienne et récente","Compréhension et communication","Force et endurance musculaires"],"r":[0,1,2],"e":"Vision/audition, mémoire ancienne et récente, compréhension et communication.","s":5},{"q":"Quels dispositifs de monitorage ou de thérapeutique faut-il repérer ?","o":["Sonde nasogastrique","Masque à oxygène","Cathéter central","Sonde urinaire","Un spiromètre incitatif"],"r":[0,1,2,3],"e":"Ces quatre dispositifs renseignent sur le degré d'intervention thérapeutique.","s":5},{"q":"Quels états psycho-émotionnels faut-il repérer ?","o":["Anxiété","Dépression","Indifférence","Labilité émotionnelle","Euphorie"],"r":[0,1,2,3],"e":"Ces quatre états font partie de l'appréciation de l'aspect général.","s":5},{"q":"Que traduit une respiration paradoxale ?","o":["Une inversion du mouvement du diaphragme","Une obstruction haute des voies aériennes","Une hypoxémie centrale avec cyanose","Un effort inspiratoire normal au repos"],"r":0,"e":"La respiration paradoxale correspond à l'inversion du mouvement diaphragmatique ; le stridor traduit une obstruction haute et la cyanose centrale une hypoxémie.","s":5},{"q":"Quel signe d'effort respiratoire est qualifié de classique chez l'enfant comme chez l'adulte ?","o":["Le battement des ailes du nez","Le hippocratisme digital","La turgescence jugulaire","L'œdème des membres inférieurs"],"r":0,"e":"Le battement des ailes du nez est un signe classique d'effort respiratoire, aux côtés du tirage et de la respiration paradoxale.","s":5},{"q":"Quels muscles accessoires faut-il examiner au niveau du cou ?","o":["Le sterno-cléido-mastoïdien","Les scalènes","Le trapèze inférieur","Le grand dorsal"],"r":[0,1],"e":"On recherche l'utilisation et l'hypertrophie du SCM et des scalènes, ainsi que la turgescence jugulaire.","s":5},{"q":"Sous quels angles évalue-t-on la posture ?","o":["Vue antérieure","Vue latérale","Vue postérieure","Vue supérieure"],"r":[0,1,2],"e":"On évalue tête, épaules, thorax, colonne, genoux et pieds en vues antérieure, latérale et postérieure.","s":5},{"q":"Quelles conséquences le thorax en tonneau traduit-il ?","o":["Une hyperinsufflation pulmonaire","Une horizontalisation des arcs costaux","Un aplatissement des coupoles","Une restriction par distorsion du poumon"],"r":[0,1,2],"e":"Le thorax en tonneau, avec augmentation des trois diamètres surtout antéro-postérieur, traduit une hyperinsufflation — BPCO, asthme. La distorsion pulmonaire caractérise le thorax cyphoscoliotique.","s":5},{"q":"Qu'est-ce qui caractérise le thorax cyphotique ?","o":["Un diamètre antéro-postérieur accru vers l'arrière","Une tête souvent antériorisée dans la BPCO","Un diamètre antéro-postérieur diminué","Une rotation vertébrale avec gibbosité"],"r":[0,1],"e":"Le thorax cyphotique augmente le diamètre AP vers l'arrière et s'associe dans la BPCO à une antériorisation de la tête.","s":5},{"q":"Que provoque le pectus carinatum au niveau du sternum et des cartilages ?","o":["Un sternum déplacé vers l'avant","Des cartilages adjacents déprimés","Une dépression du sternum","Une rotation vertébrale"],"r":[0,1],"e":"Pectus carinatum : sternum vers l'avant et cartilages adjacents déprimés. Le pectus excavatum déprime au contraire le sternum.","s":5},{"q":"Quels paramètres inspecte-t-on dans la ventilation ?","o":["La symétrie","Le rapport inspiration/expiration","La localisation du mouvement","Le rythme, régulier ou non","La saturation en oxygène"],"r":[0,1,2,3],"e":"Ces quatre paramètres structurent l'inspection de la ventilation. Localisation : costale supérieure, costale inférieure ou abdomino-diaphragmatique.","s":5},{"q":"Comment définit-on la bradypnée dans ce cours ?","o":["Une fréquence diminuée, une respiration plus profonde","Une fréquence accrue, une respiration superficielle","Une cessation de la respiration de plus de 20 secondes","Une profondeur accrue, une fréquence normale"],"r":0,"e":"Bradypnée : fréquence diminuée, respiration plus profonde, rythme régulier. Le rythme reste régulier.","s":5},{"q":"À quelles lésions la respiration de Cheyne-Stokes et celle de Biot sont-elles associées ?","o":["Cheyne-Stokes : lésions cérébrales par hypoxie","Biot : lésions du bulbe, de mauvais pronostic","Cheyne-Stokes : lésions du tronc cérébral","Biot : lésions médullaires, de bon pronostic"],"r":[0,1],"e":"Cheyne-Stokes : lésions cérébrales par hypoxie. Biot (ataxique) : lésions du bulbe, mauvais pronostic. Apneustique : lésions du tronc cérébral.","s":5},{"q":"Quelle est la séquence de la respiration de Kussmaul ?","o":["Inspiration rapide et profonde, pause, expiration soudaine, pause","Profondeur croissante puis décroissante, puis apnée","Cycles irréguliers en profondeur et en fréquence","Inspiration profonde, apnée prolongée, expiration lente, apnée"],"r":0,"e":"Kussmaul : inspiration rapide et profonde, pause, expiration soudaine, nouvelle pause.","s":5},{"q":"Quels muscles palpe-t-on pour évaluer le tonus en kinésithérapie respiratoire ?","o":["Les muscles accessoires","La paroi abdominale","Les paravertébraux","Les trapèzes","Le diaphragme"],"r":[0,1,2,3],"e":"On palpe aussi les sensations tactiles anormales (frottements, ronchi), les points douloureux et les caractéristiques de la peau.","s":5},{"q":"Où place-t-on l'index pour rechercher une déviation trachéale ?","o":["Dans l'incisure supra-sternale, en dedans de la sterno-claviculaire","Sur le cartilage cricoïde, juste sous le cartilage thyroïde","Sur la ligne mamelonnaire, au niveau du 4ᵉ espace intercostal","Dans le pli axillaire antérieur, au bord du grand pectoral"],"r":0,"e":"Index dans l'incisure supra-sternale, en dedans de l'articulation sterno-claviculaire, à droite puis à gauche, en poussant vers l'intérieur en direction de la clavicule.","s":5},{"q":"Quel lobe explore la mobilité thoracique qualitative apicale, et où se place le kiné ?","o":["Le lobe supérieur, le kiné face antérieure","Le lobe moyen, le kiné face antérieure","Le lobe inférieur, le kiné face postérieure","La lingula, le kiné en position latérale"],"r":0,"e":"Apicale ou costale supérieure : lobe supérieur, face antérieure. Costale moyenne : lobe moyen à droite, lingula à gauche, face antérieure. Costale inférieure : lobe inférieur, face postérieure.","s":5},{"q":"Quelle variation de périmètre est attendue au niveau de l'appendice xiphoïde ?","o":["4-5 cm","2-3 cm","7-8 cm","10 cm"],"r":0,"e":"Pli axillaire 2-3 cm, appendice xiphoïde 4-5 cm, cicatrice ombilicale 7-8 cm.","s":5},{"q":"Quel virus est responsable de la majorité des bronchiolites ?","o":["Le virus respiratoire syncytial, dans 70 à 90 % des cas","L'adénovirus, dans 40 à 50 % des cas","Le rhinovirus, dans 30 à 40 % des cas","Le métapneumovirus humain, dans 60 à 70 % des épisodes"],"r":0,"e":"Les autres virus en cause sont l'influenza A et B, le para-influenza 1 et 3 et l'adénovirus.","s":6},{"q":"À quel âge l'incidence de la bronchiolite est-elle maximale ?","o":["Entre 3 et 6 mois","Entre 1 et 2 ans","Entre 2 et 3 ans","À la naissance"],"r":0,"e":"C'est l'infection respiratoire la plus fréquente chez l'enfant de moins de 2 ans.","s":6},{"q":"Quelle proportion des hospitalisations pour VRS concerne les nourrissons de moins de 6 mois ?","o":["67 %","30 %","85 %","10 %"],"r":0,"e":"L'incidence maximale se situe entre 3 et 6 mois.","s":6},{"q":"Quelle est la période épidémique de la bronchiolite ?","o":["Entre novembre et mars","Entre mai et août","Toute l'année sans variation","Entre juillet et septembre"],"r":0,"e":"Elle évolue par épidémies saisonnières.","s":6},{"q":"Quel anticorps monoclonal a été approuvé pour la saison 2024/2025 ?","o":["Le nirsévimab","Le palivizumab","L'omalizumab","Le rituximab"],"r":0,"e":"Il est administré aux nouveau-nés, prématurés et groupes à risque.","s":6},{"q":"Où se localise la bronchiolite ?","o":["Dans les bronchioles terminales","Dans les alvéoles pulmonaires","Dans le larynx et la trachée","Dans le rhinopharynx seulement"],"r":0,"e":"Ses manifestations cliniques sont de type obstructif.","s":6},{"q":"Quels signes caractérisent la phase précoce de la bronchiolite (48 premières heures) ?","o":["Obstruction nasale, rhinorrhée, toux sèche, sibilants","Tachypnée, fièvre élevée, tirage, refus alimentaire","Toux résiduelle isolée, sans autre signe","Apnées, cyanose, épuisement, troubles de conscience"],"r":0,"e":"La phase d'aggravation survient du 3ᵉ au 5ᵉ jour.","s":6},{"q":"Combien de temps peut persister la toux résiduelle après une bronchiolite ?","o":["Jusqu'à 2 à 3 semaines","24 heures au maximum","3 jours au maximum","Jusqu'à 6 mois"],"r":0,"e":"La phase d'amélioration s'observe du 5ᵉ au 7ᵉ jour.","s":6},{"q":"Après combien de temps la bronchiolite évolue-t-elle des voies supérieures vers les voies inférieures ?","o":["Après 48 à 72 heures","Après 6 heures","Après 10 jours","Immédiatement"],"r":0,"e":"On observe alors une augmentation du travail respiratoire et une respiration sifflante.","s":6},{"q":"Quelle est la cause bactérienne la plus fréquente de pneumonie chez l'enfant ?","o":["Streptococcus pneumoniae","Haemophilus influenzae type b","Le VRS","Le staphylocoque doré"],"r":0,"e":"Haemophilus influenzae type b est la deuxième cause bactérienne ; le VRS est la première cause virale.","s":6},{"q":"Combien d'enfants de moins de 5 ans meurent chaque année de pneumonie ?","o":["Environ 1,2 million","Environ 10 000","Environ 100 000","Environ 10,5 millions"],"r":0,"e":"C'est la principale cause de mortalité infantile dans le monde selon l'OMS.","s":6},{"q":"Pourquoi la toux n'est-elle pas une caractéristique initiale de la pneumonie ?","o":["Les alvéoles ne se drainent pas par la toux","Le réflexe de toux est absent avant 2 ans","La fièvre élevée inhibe le réflexe de toux","L'enfant est trop jeune pour savoir tousser"],"r":0,"e":"La fièvre et la tachypnée peuvent apparaître avant la toux.","s":6},{"q":"Quel mécanisme d'obstruction relève de la kinésithérapie respiratoire ?","o":["L'hypersécrétion, qui donne des râles","L'œdème, qui donne des sibilants","Le bronchospasme, qui donne des sibilants","L'inflammation, qui donne un stridor"],"r":0,"e":"L'œdème et le bronchospasme relèvent de la thérapie médicamenteuse.","s":6},{"q":"Quand la kinésithérapie respiratoire est-elle très utile en pédiatrie ?","o":["Sécrétions abondantes ou adhérentes, trouble mécanique","Toute fièvre de l'enfant, même sans aucun encombrement bronchique","Un bronchospasme isolé, sans sécrétions","Un œdème muqueux isolé, sans sécrétions"],"r":0,"e":"Elle est symptomatique et suit la séquence fluidification, décollement, progression, élimination.","s":6},{"q":"Pourquoi l'évaluation doit-elle être un processus dynamique en pédiatrie ?","o":["L'état de l'enfant change vite et souvent pendant la séance","Les parents demandent à voir chaque étape de la séance","La durée de la séance doit être respectée à la minute","La facturation de l'acte doit être justifiée par écrit"],"r":0,"e":"L'usage de techniques inadaptées peut aggraver l'état de l'enfant et mettre sa vie en danger.","s":6},{"q":"Quelle échelle de douleur figure parmi celles citées en pédiatrie ?","o":["FLACC","Borg","VAS-fatigue","Barthel"],"r":0,"e":"On cite aussi EDIN, NIPS, PIPP et N-PASS.","s":6},{"q":"Quel signe fait partie des red flags en pédiatrie ?","o":["Des vomissements en jet ou persistants","Une toux productive en fin de séance","Une rhinorrhée claire depuis deux jours","Un sommeil calme entre les tétées"],"r":0,"e":"On retient aussi les apnées, le refus alimentaire, la fièvre persistante et l'âge inférieur à 6 mois.","s":6},{"q":"Pourquoi le bruit respiratoire a-t-il un caractère bronchique chez l'enfant de moins de 2 ans ?","o":["Paroi fine, alvéoles moins nombreuses, distance d'écoute courte","Poumons infectés, sécrétions abondantes, fièvre persistante","Stéthoscope inadapté, pavillon trop large, bruit ambiant","Pleurs, agitation, respiration buccale, déglutition"],"r":0,"e":"Ce caractère bronchique est considéré comme normal avant 2 ans. S'y ajoutent une densité du parenchyme et un nombre de voies aériennes plus élevés.","s":6},{"q":"Entre quels âges le timbre du bruit respiratoire évolue-t-il principalement ?","o":["Entre 0 et 12 ans","Entre 12 et 18 ans","Entre 0 et 2 ans","Après 18 ans"],"r":0,"e":"Il évolue parallèlement à la croissance.","s":6},{"q":"Quelle est la durée des râles de basse fréquence ?","o":["15 à 30 ms","8 à 15 ms","Moins de 8 ms","Plus de 30 ms"],"r":0,"e":"Ce sont des bruits rudes, de type encombrement, normalement aléatoires ou protophasiques.","s":6},{"q":"Quelle est la durée des râles de haute fréquence ?","o":["Moins de 8 ms","8 à 15 ms","15 à 30 ms","Plus de 30 ms"],"r":0,"e":"Ce sont des bruits fins, type frottement de cheveux ou papier cellophane.","s":6},{"q":"Quelle est la durée minimale d'un sibilant ?","o":["Plus de 30 ms","Moins de 8 ms","15 ms","30 ms exactement"],"r":0,"e":"Les râles, eux, sont des bruits discontinus dont la durée n'excède pas 30 ms.","s":6},{"q":"À partir de quel taux de sibilants ne faut-il pas intervenir ?","o":["Supérieur à 50/60 %","Supérieur à 10 %","Supérieur à 90 %","Il n'y a pas de seuil"],"r":0,"e":"Le taux de sibilants est une donnée importante pour le choix de l'intervention.","s":6},{"q":"À quelle structure faut-il prêter une attention particulière à l'auscultation du nourrisson ?","o":["Au lobe moyen, siège d'atélectasies fréquentes","Au lobe supérieur droit, siège de pneumonies","À la lingula, siège de bronchectasies","Aux apex, siège de pneumothorax"],"r":0,"e":"Le décubitus latéral n'est utilisé qu'après 6/8 ans pour l'auscultation.","s":6},{"q":"À quel âge la DRR est-elle indiquée ?","o":["Chez l'enfant de moins de 2 ans","Chez l'enfant de plus de 2 ans","Chez l'enfant de plus de 6 ans","À tout âge, adulte compris"],"r":0,"e":"C'est une manœuvre inspiratoire forcée de désobstruction du rhinopharynx.","s":6},{"q":"Que faut-il faire des mouche-bébés aspirateurs ?","o":["Ne pas les utiliser","Les utiliser systématiquement","Les réserver aux plus de 2 ans","Les utiliser avant chaque séance"],"r":0,"e":"La douche nasale est la technique retenue pour les voies extra-thoraciques.","s":6},{"q":"Jusqu'à quel âge le réflexe de toux provoquée se maintient-il ?","o":["Jusqu'à 3-4 ans","Jusqu'à 1 an","Jusqu'à 8 ans","Toute la vie"],"r":0,"e":"Il repose sur la stimulation des mécanorécepteurs de la trachée extra-thoracique.","s":6},{"q":"Quelles sont les contre-indications de la toux provoquée ?","o":["Affection du larynx avec stridor, toux non productive","Hypersécrétion abondante, toux grasse et productive","Bronchiolite aiguë, avec râles et sibilants","Pneumonie lobaire, avec fièvre et crépitants"],"r":0,"e":"Elle est réalisée dans la continuité de l'ELPr.","s":6},{"q":"Pourquoi l'AFE est-elle contre-indiquée avant 2 ans ?","o":["Risque de collapsus bronchique, de fracture de côte, de hausse de PIC","Risque d'inefficacité, car la glotte reste fermée, sans DEP utile","Elle est trop lente, car l'expiration dure plus de 10 secondes","Elle est inutile, car les sécrétions sont toujours proximales"],"r":0,"e":"L'AFE requiert le maintien de la glotte ouverte.","s":6},{"q":"Que dit le paradigme du poumon profond ?","o":["Inspiratoires d'abord, car l'obstruction débute en distal","Expiratoires d'abord, car l'obstruction débute en proximal","Proximal seul, car le distal se draine de lui-même","Aucun positionnement, car seule la manœuvre compte"],"r":0,"e":"L'obstruction bronchique proximale n'est que l'émergence distante d'une infection distale.","s":6},{"q":"À quel âge et dans quelles positions réalise-t-on la DRR ?","o":["Chez l'enfant de moins de 2 ans","En position assise ou semi-Fowler","Chez l'enfant de plus de 5 ans","En décubitus ventral"],"r":[0,1],"e":"La désobstruction rhinopharyngée rétrograde est une manœuvre inspiratoire forcée, chez l'enfant de moins de 2 ans, en position assise ou semi-Fowler.","s":6},{"q":"Comment ferme-t-on la bouche en fin d'expiration lors de la DRR ?","o":["En obstruant avec la main ou une compresse","En fermant la mandibule, prudemment","En poussant la base de la langue au palais","En pinçant les deux narines en même temps"],"r":[0,1,2],"e":"Trois procédés sont décrits, après avoir prolongé le plus possible l'expiration par les pleurs ou l'ELPr.","s":6},{"q":"Quelles options peuvent augmenter le flux lors de la DRR ?","o":["Mettre quelques gouttes de sérum dans une narine","Fermer l'autre narine","Simuler un mouchage passif en fin d'inspiration","Utiliser un mouche-bébé aspirateur"],"r":[0,1,2],"e":"Ces trois options sont décrites. Les mouche-bébés aspirateurs sont explicitement à ne pas utiliser. Le mouchage passif consiste à fermer la bouche et la narine opposée.","s":6},{"q":"Où et comment déclenche-t-on la toux provoquée ?","o":["Par une pression brève du pouce au-dessus de la fourchette","En fin d'inspiration ou en début d'expiration","Par stimulation des mécanorécepteurs trachéaux","Par compression du thorax en fin d'expiration"],"r":[0,1,2],"e":"La toux provoquée stimule les mécanorécepteurs de la paroi trachéale extra-thoracique, par une pression brève au-dessus de la fourchette sternale. Le pouce est placé transversalement à la trachée extra-thoracique.","s":6},{"q":"Dans quelles positions peut-on réaliser la toux provoquée ?","o":["Nourrisson couché","Assis","En position avion","Debout, sans soutien"],"r":[0,1,2],"e":"Trois positions, avec tête en extension, pression sèche et brève sur la fourchette sternale et compression abdominale avec la paume. La position avion déclenche le réflexe de redressement.","s":6},{"q":"En quoi consiste la glossopulsion rétrograde ?","o":["Ramener à la commissure les sécrétions de l'oropharynx","Pousser la base de la langue au palais juste après la toux","Chez l'enfant de moins de 2 ans","Aspirer les sécrétions à la canule de Yankauer"],"r":[0,1,2],"e":"C'est une manœuvre de l'enfant de moins de 2 ans, à réaliser uniquement si l'on doit évaluer les propriétés rhéologiques des sécrétions.","s":6},{"q":"Pourquoi la glossopulsion rétrograde n'est-elle pas systématique ?","o":["Les sécrétions peuvent être dégluties sans problème","Elle reste douloureuse pour l'enfant","Elle provoque presque toujours des vomissements","Elle est contre-indiquée avant l'âge de 2 ans"],"r":0,"e":"Elle ne se réalise que si l'on doit évaluer les propriétés rhéologiques des sécrétions : leur déglutition ne pose pas de problème.","s":6},{"q":"Sous quelles formes l'AFE peut-elle être réalisée en pédiatrie ?","o":["Active","Active-assistée","Passive","Instrumentale"],"r":[0,1,2],"e":"Active, active-assistée ou passive, à haut volume (sécrétions proximales) ou bas volume (distales), en maintenant la glotte ouverte.","s":6},{"q":"Comment définit-on l'ELPr ?","o":["Une pression manuelle thoraco-abdominale lente","Débutant à la fin d'une expiration spontanée","Jusqu'à environ 50 % du volume expiratoire","Une manœuvre inspiratoire forcée et brève"],"r":[0,1,2],"e":"L'ELPr vise un volume expiratoire supérieur à celui d'une expiration normale.","s":6},{"q":"Comment réalise-t-on l'ELPr ?","o":["En semi-Fowler ou assis","Une main thoracique, une abdominale","Une pression lente contre 2 ou 3 inspirations","Pas de pression au début de l'expiration","En décubitus ventral strict, tête tournée"],"r":[0,1,2,3],"e":"Les quatre éléments décrivent la technique.","s":6},{"q":"Que postule le paradigme du poumon profond ?","o":["Le poumon profond est le site prioritaire du traitement","L'obstruction part des voies aériennes distales","L'obstruction proximale est l'émergence d'une infection distale","L'obstruction commence dans les grosses bronches"],"r":[0,1,2],"e":"Les trois premiers points fondent le paradigme, qui inverse la logique de l'école anglo-saxonne.","s":6},{"q":"Quelles conséquences pratiques découlent du paradigme du poumon profond ?","o":["Inspirations lentes, résistées, et positionnement","Techniques inspiratoires avant expiratoires","Résister à 2 ou 3 inspirations pendant l'ELPr","Expirations forcées à privilégier d'emblée"],"r":[0,1,2],"e":"Trois conséquences pratiques, opposées au recours aux expirations forcées. Après la résistance, on favorise une inspiration lente à haut volume ou un soupir.","s":6},{"q":"Quelle proportion du médicament nébulisé est réellement absorbée ?","o":["10 à 20 % du total délivré","50 à 60 % du total délivré","80 à 90 % du total délivré","La totalité du médicament délivré"],"r":0,"e":"Seuls 10 à 20 % du médicament délivré sont effectivement absorbés.","s":6},{"q":"Quels sont les objectifs de l'aérosolthérapie par nébulisation en pédiatrie ?","o":["Fluidifier et aider à éliminer les sécrétions","Hydrater la muqueuse, apporter un médicament local","Diminuer le bronchospasme et l'inflammation","Améliorer le transport mucociliaire avant la séance","Stériliser les voies aériennes avant la séance"],"r":[0,1,2,3],"e":"Sept objectifs sont énumérés dans la fiche.","s":6},{"q":"Pourquoi les aérosols en excès sont-ils délétères ?","o":["Ils irritent les bronches","Ils augmentent les sécrétions","Ils diminuent la saturation","Ils provoquent une alcalose"],"r":[0,1],"e":"Les aérosols en excès sont un facteur d'irritation bronchique et d'augmentation des sécrétions : ils ne sont utiles que réellement indiqués.","s":6},{"q":"Quelles règles d'hygiène encadrent l'aérosolthérapie ?","o":["Nettoyage après chaque utilisation","Accessoires personnels, non partagés","Ne pas réutiliser le sérum du nettoyage nasal","Stérilisation hebdomadaire obligatoire"],"r":[0,1,2],"e":"Trois règles d'hygiène sont énoncées.","s":6},{"q":"Par quels mécanismes la solution salée hypertonique à 3 % agit-elle ?","o":["Elle rompt les liaisons ioniques du gel muqueux, réduisant les cross-links","Elle induit un flux osmotique d'eau vers le mucus, le réhydratant","Elle stimule les battements ciliaires par libération de prostaglandines E2","Elle augmente l'absorption d'eau de la muqueuse et de la sous-muqueuse","Elle neutralise directement le virus respiratoire syncytial"],"r":[0,1,2,3],"e":"Ces quatre mécanismes augmentent la clairance muco-ciliaire et abaissent viscosité et élasticité du mucus.","s":6},{"q":"Quel effet théorique la solution hypertonique peut-elle avoir dans la bronchiolite aiguë ?","o":["Réduire l'œdème des parois","Éliminer le virus","Supprimer la toux","Augmenter le volume courant"],"r":0,"e":"La SH 3 % peut théoriquement réduire l'œdème des parois chez l'enfant atteint de bronchiolite aiguë.","s":6},{"q":"Quelle est la procédure d'utilisation d'une chambre d'inhalation chez l'enfant de moins de 5 ans ?","o":["Retirer le capuchon, agiter à la verticale, insérer dans la chambre","Adapter le masque au visage en couvrant bouche et nez","Respirer normalement pendant 10 à 15 secondes","Réaliser une apnée télé-inspiratoire de 5 secondes"],"r":[0,1,2],"e":"L'apnée télé-inspiratoire de 5 secondes concerne l'enfant de plus de 5-6 ans.","s":6},{"q":"Quelle est la procédure pour l'enfant de plus de 5-6 ans avec chambre d'inhalation ?","o":["Après une expiration profonde, inspirer lentement et à fond","Apnée télé-inspiratoire de 5 secondes","Expirer lentement par la bouche","Respirer normalement pendant 10 à 15 secondes"],"r":[0,1,2],"e":"À partir de 5-6 ans, l'idéal est d'utiliser un embout buccal, avec cette séquence.","s":6},{"q":"Comment doit-on aborder les muscles respiratoires ?","o":["Comme les autres muscles : mobilité, étirement, force, endurance","Par la relaxation seule : détente, respiration lente, sommeil","Par l'aérosol seul : fluidifier, hydrater, dilater les bronches","Par la ventilation seule : machine, masque, pression positive, réglages"],"r":0,"e":"La qualité de leur mouvement doit également être assurée.","s":7},{"q":"À quoi correspond l'amplitude de mouvement pour les muscles respiratoires ?","o":["Au volume qu'on parvient à inspirer","À la pression inspiratoire maximale","Au temps d'inspiration contre résistance","Au schéma ventilatoire du patient"],"r":0,"e":"La force correspond à la PIM et l'endurance au temps d'inspiration contre résistance.","s":7},{"q":"À quoi correspond la qualité du mouvement respiratoire ?","o":["Au schéma ventilatoire","À la force maximale","Au volume inspiré","À la fréquence respiratoire"],"r":0,"e":"C'est l'un des quatre paramètres à considérer avec l'amplitude, la force et l'endurance.","s":7},{"q":"Que traduit la pression inspiratoire maximale (PIM) ?","o":["La force du diaphragme et des intercostaux, en pression négative","La force des abdominaux et des intercostaux, en pression positive","Le volume courant au repos, mesuré en litres au spiromètre","La compliance du thorax, mesurée en mL/cmH₂O au repos"],"r":0,"e":"La PEM traduit la force des abdominaux et des intercostaux, en pressions positives.","s":7},{"q":"Que traduit la pression expiratoire maximale (PEM) ?","o":["La force des abdominaux et des intercostaux, en pression positive","La force du diaphragme et des scalènes, en pression négative maximale","L'endurance inspiratoire, en secondes","Le débit expiratoire de pointe, en L/min"],"r":0,"e":"Les deux valeurs sont exprimées en pourcentage des valeurs attendues pour l'âge et le sexe.","s":7},{"q":"Dans quelle classe de pathologies se situe la sclérose latérale amyotrophique ?","o":["Les dégénératives, parmi les maladies neuromusculaires","Les congénitales, parmi les maladies génétiques","Les aiguës ou traumatiques, parmi les lésions médullaires et chirurgicales","Les infectieuses, parmi les maladies virales"],"r":0,"e":"On y trouve aussi le syndrome de Guillain-Barré, la myasthénie et les dystrophies musculaires.","s":7},{"q":"Dans quelle classe se situent la mucoviscidose et la poliomyélite ?","o":["Les congénitales/génétiques","Les dégénératives","Les aiguës/traumatiques","Les post-chirurgicales"],"r":0,"e":"Les lésions médullaires et les suites post-chirurgicales sont classées comme aiguës/traumatiques.","s":7},{"q":"Le vieillissement en bonne santé est-il une indication de l'EMI ?","o":["Oui, il figure parmi les indications","Non, c'est une contre-indication chez l'âgé","Oui, mais seulement après 80 ans","Non, sauf avec une pathologie associée"],"r":0,"e":"Référence : McConnell, 2013.","s":7},{"q":"Existe-t-il des effets indésirables décrits de l'EMI ?","o":["Non, seulement un risque théorique de barotraumatisme","Oui, de nombreux effets graves, surtout cardiaques","Oui, un risque hémorragique, surtout chez l'âgé","Oui, un risque infectieux majeur, lié à l'embout"],"r":0,"e":"Des précautions sont néanmoins recommandées dans certaines situations.","s":7},{"q":"Quelle situation impose une précaution particulière avant l'EMI ?","o":["Un antécédent de pneumothorax spontané","Une BPCO stable sous traitement","Une dyspnée d'effort modérée","Une intolérance à l'exercice chez un patient opéré du cœur"],"r":0,"e":"On retient aussi le pneumothorax traumatique non cicatrisé, la perforation tympanique et la chirurgie oculaire récente ou le glaucome.","s":7},{"q":"Quels patients ne doivent pas être soumis à l'EMI ?","o":["Ceux qui ont un asthme instable, peu sensible à la dyspnée","Tous les patients BPCO, quel que soit leur stade","Les patients âgés de plus de 75 ans","Les patients post-opératoires de chirurgie thoracique ou abdominale"],"r":0,"e":"Références : Cooper 2012 ; McConnell 2013.","s":7},{"q":"Quelle est la taille de l'orifice de fuite de l'embout de mesure des PRM ?","o":["1 à 2 mm de diamètre interne","5 à 6 mm de diamètre interne, pour limiter la résistance","0,1 mm de diamètre interne","10 mm de diamètre interne"],"r":0,"e":"L'embout est de type plongeur, semi-rigide.","s":7},{"q":"Dans quelle position se mesurent les pressions respiratoires maximales ?","o":["Assis, tronc à 90° des membres inférieurs, sans vêtement serré","Debout, bras levés à 90°, sans vêtement serré","Décubitus dorsal, tête surélevée à 30°, sans vêtement serré","Décubitus latéral, hanches fléchies à 45°, sans vêtement serré"],"r":0,"e":"Les manœuvres doivent être soigneusement expliquées au préalable.","s":7},{"q":"À quel volume se mesure la PImax ?","o":["Au niveau du volume résiduel","Au niveau de la capacité pulmonaire totale","Au niveau du volume courant","Au niveau de la CRF"],"r":0,"e":"La PEmax se mesure au niveau de la CPT.","s":7},{"q":"À quel volume se mesure la PEmax ?","o":["Au niveau de la capacité pulmonaire totale","Au niveau du volume résiduel","Au niveau de la capacité résiduelle fonctionnelle","Au niveau du volume courant"],"r":0,"e":"La PImax se mesure au niveau du volume résiduel.","s":7},{"q":"Combien de temps l'effort doit-il être soutenu lors de la mesure ?","o":["Au moins deux secondes","Au moins dix secondes","Une demi-seconde","Cinq minutes"],"r":0,"e":"Le repos entre chaque manœuvre est d'au moins une minute.","s":7},{"q":"Combien de manœuvres doit-on réaliser ?","o":["Au moins 5, en gardant les deux valeurs les plus élevées","Exactement 3, en gardant la moyenne des trois valeurs mesurées","Une seule, si elle est bien réalisée","Au moins 10, en gardant la dernière"],"r":0,"e":"La reproductibilité entre les deux valeurs retenues doit être ≤ 5 %.","s":7},{"q":"Quelle reproductibilité est exigée entre les deux meilleures valeurs ?","o":["≤ 5 %","≤ 20 %","≤ 50 %","Aucune exigence"],"r":0,"e":"Le repos entre les manœuvres est d'au moins une minute.","s":7},{"q":"Quelles équations de référence sont proposées à défaut de valeurs portugaises ?","o":["Celles de Wilson et coll., population anglaise dès sept ans","Celles de McConnell et coll., population anglaise adulte, dès dix-huit ans","Celles de Vergara et coll., population espagnole","Celles de Downey et coll., population américaine"],"r":0,"e":"Leur méthodologie est la plus proche du protocole décrit.","s":7},{"q":"Que penser des charges externes posées sur l'abdomen comme dispositif d'entraînement ?","o":["Elles sont à proscrire","Elles sont recommandées en première intention","Elles équivalent au Threshold IMT","Elles sont réservées aux patients neurologiques"],"r":0,"e":"Les appareils flow-resistive ont l'inconvénient d'une résistance dépendante du débit du patient.","s":7},{"q":"Quel est l'inconvénient des dispositifs flow-resistive ?","o":["La résistance dépend du débit utilisé par le patient","Ils coûtent trop cher pour un usage à domicile","Ils ne se nettoient pas entre deux séances","Ils imposent un masque facial au lieu d'un embout"],"r":0,"e":"Les Threshold ont au contraire une valve indépendante du débit.","s":7},{"q":"Quelle est la plage de pressions du Threshold IMT ?","o":["7-41 cmH₂O, par paliers de 2 cmH₂O","5-20 cmH₂O, par paliers de 1 cmH₂O","10-90 cmH₂O, par paliers de 10 cmH₂O","9-78 cmH₂O, par paliers de 7 cmH₂O"],"r":0,"e":"Le Threshold PEP couvre 5-20 cmH₂O par paliers de 1 cmH₂O.","s":7},{"q":"Quelle est la plage du Threshold PEP ?","o":["5-20 cmH₂O","7-41 cmH₂O","10-20 cmH₂O","10-90 cmH₂O"],"r":0,"e":"Sa valve unidirectionnelle est expiratoire et indépendante du débit.","s":7},{"q":"Quel dispositif POWERbreathe® possède une valve électronique ?","o":["Le modèle KH1","Le Medica Classic","Le Medic Plus","Aucun, les 3 sont des IMT manuels"],"r":0,"e":"Il couvre 10-20 cmH₂O par paliers de 1 cmH₂O, entraîne le schéma respiratoire et mémorise les séances.","s":7},{"q":"Quelle est la particularité de l'AIROFIT® ?","o":["Deux valves manuelles, Bluetooth, guidage du schéma respiratoire","Une valve inspiratoire unique, sans réglage","Une résistance dépendante du débit, sans application ni guidage d'aucune sorte","Aucune mémorisation des séances, ni guidage"],"r":0,"e":"Son application propose plusieurs programmes d'évaluation et d'entraînement.","s":7},{"q":"Quelle intensité recommande-t-on chez l'individu en bonne santé ?","o":["50-70 % de la PIM","30-50 % de la PIM","10-20 % de la PIM","80-100 % de la PIM"],"r":0,"e":"Chez les patients, on retient environ 30-50 % de la PIM.","s":7},{"q":"Quelle est la durée d'une séance chez l'individu en bonne santé ?","o":["30 cycles respiratoires, soit 2 à 3 minutes","10 à 30 minutes, soit environ 150 à 450 cycles respiratoires","1 heure d'affilée, soit 900 cycles","5 cycles respiratoires, soit 20 secondes"],"r":0,"e":"Chez les patients, la durée est de 10 à 30 min pendant 2 à 3 mois.","s":7},{"q":"Après combien de temps les adaptations musculaires sont-elles évidentes chez le patient ?","o":["Après 6 semaines","Après 3-4 semaines","Après 1 semaine","Après 6 mois"],"r":0,"e":"Chez le sujet sain, elles apparaissent après 3-4 semaines.","s":7},{"q":"Selon le protocole de Vergara (2004), que faire si la PIM n'est pas diminuée ?","o":["Ne pas débuter l'entraînement","Débuter à 25 % de la PIM","Débuter à 70 % de la PIM","Entraîner uniquement les expirateurs"],"r":0,"e":"L'entraînement ne débute que si la PIM est diminuée.","s":7},{"q":"Quelle est la première étape du protocole de Vergara une fois l'entraînement décidé ?","o":["7 à 10 jours à 25 % de la PIM, 15 min deux fois par jour","30 jours à 70 % de la PIM, 30 min une fois par jour, avant tout renforcement","3 jours à 50 % de la PIM, 15 min deux fois par jour","2 semaines à 10 % de la PIM, 5 min par jour"],"r":0,"e":"On réévalue ensuite la PIM et on entraîne à 30 % des nouvelles valeurs, avec un renforcement à 60-70 % tous les 7-8 cycles.","s":7},{"q":"À quoi correspondent la force et l'endurance pour les muscles respiratoires ?","o":["Force : la pression inspiratoire maximale","Endurance : le temps d'inspiration contre résistance","Force : le volume inspiré en une seule inspiration","Endurance : le schéma ventilatoire au repos"],"r":[0,1],"e":"Amplitude = volume inspiré · force = PIM · endurance = temps d'inspiration contre résistance · qualité du mouvement = schéma ventilatoire.","s":7},{"q":"Quelles pathologies dégénératives neuromusculaires affectent les muscles respiratoires ?","o":["Sclérose latérale amyotrophique","Syndrome de Guillain-Barré","Myasthénie","Dystrophies musculaires","Mucoviscidose de l'adulte"],"r":[0,1,2,3],"e":"Ces quatre maladies sont classées parmi les dégénératives neuromusculaires.","s":7},{"q":"Quelles atteintes sont classées comme aiguës ou traumatiques ?","o":["Lésion médullaire","Suites post-chirurgicales","Mucoviscidose","Myasthénie grave"],"r":[0,1],"e":"Lésion médullaire et suites post-chirurgicales sont aiguës/traumatiques. La mucoviscidose est congénitale, la myasthénie dégénérative.","s":7},{"q":"Quelles indications de l'entraînement des muscles inspiratoires McConnell (2013) retient-il ?","o":["Dyspnée et intolérance à l'exercice","Pathologies respiratoires, cardiaques, neuromusculaires","Vieillissement en bonne santé","Déséquilibre charge/capacité des muscles inspiratoires","Asthme instable, peu sensible à la dyspnée"],"r":[0,1,2,3],"e":"Quatre familles d'indications, les indicateurs physiologiques comprenant force inspiratoire réduite, dyspnée, hyperinsufflation et incapacité à respirer sans support ventilatoire. Les pathologies chirurgicales en font aussi partie.","s":7},{"q":"Quelles précautions entourent l'entraînement des muscles inspiratoires ?","o":["Antécédent de pneumothorax spontané","Pneumothorax traumatique non cicatrisé","Perforation du tympan non cicatrisée","Chirurgie oculaire récente ou glaucome","Hypertension artérielle contrôlée"],"r":[0,1,2,3],"e":"Ces quatre précautions découlent du risque théorique de barotraumatisme, aucun effet indésirable de l'EMI n'étant décrit.","s":7},{"q":"Comment les pressions respiratoires maximales sont-elles exprimées ?","o":["En pourcentage des valeurs attendues pour l'âge et le sexe","En valeur absolue seulement, sans valeur de référence","En pourcentage de la capacité vitale mesurée le même jour","En litres par minute, comme le débit de pointe"],"r":0,"e":"Les PRM s'expriment en pourcentage des valeurs attendues pour l'âge et le sexe.","s":7},{"q":"Quel équipement est nécessaire à la mesure des pressions respiratoires maximales ?","o":["Embout plongeur semi-rigide, avec orifice de fuite","Filtre, valves inspiratoire et expiratoire, pince nasale","Pléthysmographe équipé ou manomètre portable","Enregistrement ou affichage graphique de l'examen","Oxymètre de pouls placé au doigt du patient"],"r":[0,1,2,3],"e":"L'équipement complet est décrit dans la fiche.","s":7},{"q":"Comment le patient est-il installé pour la mesure des PRM ?","o":["Assis, tronc à 90° des membres inférieurs","Sans vêtements serrés","Les mains tenant les joues","En décubitus dorsal strict"],"r":[0,1,2],"e":"Assis, tronc à 90°, sans vêtements serrés, les mains tenant les joues — le technicien coaptant les lèvres à l'embout en cas de fuite.","s":7},{"q":"Quel repos minimal sépare deux manœuvres de mesure des PRM ?","o":["Au moins une minute","Au moins 10 secondes","Au moins 5 minutes","Aucun repos, à la suite"],"r":0,"e":"Au moins une minute de repos entre chaque manœuvre, avec au moins 5 manœuvres et une reproductibilité ≤ 5 % entre les deux meilleures.","s":7},{"q":"À partir de quel âge les équations de Wilson sont-elles applicables ?","o":["À partir de sept ans","À partir de 18 ans","À partir de 12 ans","Sans limite d'âge"],"r":0,"e":"Les équations de référence de Wilson et coll. portent sur la population anglaise à partir de sept ans.","s":7},{"q":"Quelle est la plage de pressions et le pas du Threshold PEP ?","o":["5-20 cmH₂O, paliers de 1 cmH₂O","7-41 cmH₂O, paliers de 2 cmH₂O","10-90 cmH₂O, paliers de 10 cmH₂O","9-78 cmH₂O, paliers de 7 cmH₂O"],"r":0,"e":"Threshold PEP : 5-20 cmH₂O par paliers de 1. Threshold IMT : 7-41 cmH₂O par paliers de 2.","s":7},{"q":"Quelle est la particularité commune des dispositifs Threshold ?","o":["Une valve unidirectionnelle indépendante du débit","Une résistance qui dépend du débit du patient","Une valve électronique réglable par paliers","Une connexion Bluetooth à une application"],"r":0,"e":"Les Threshold PEP et IMT ont une valve unidirectionnelle indépendante du débit — contrairement aux dispositifs flow-resistive, dont la résistance dépend du débit du patient.","s":7},{"q":"Quelles sont les caractéristiques du POWERbreathe® Medic Plus ?","o":["Valve manuelle, 9-78 cmH₂O, paliers de 7 cmH₂O","Valve manuelle, 10-90 cmH₂O, paliers de 10 cmH₂O","Valve électronique, 10-20 cmH₂O","Deux valves manuelles avec Bluetooth"],"r":0,"e":"Medica Classic : 10-90 cmH₂O par paliers de 10. Medic Plus : 9-78 cmH₂O par paliers de 7. KH1 : valve électronique, 10-20 cmH₂O par paliers de 1.","s":7},{"q":"Que permet le POWERbreathe® KH1 en plus de l'entraînement en résistance ?","o":["Il entraîne le schéma respiratoire","Il mémorise les séances","Il se connecte en Bluetooth à une application","Il mesure la saturation"],"r":[0,1],"e":"Le KH1, à valve électronique, entraîne le schéma respiratoire et mémorise les séances. La connectivité Bluetooth et l'application caractérisent l'AIROFIT®.","s":7},{"q":"Quelles fonctionnalités offre l'AIROFIT® ?","o":["Deux valves manuelles, inspiratoire et expiratoire","Bluetooth et application d'entraînement","Guidage du schéma respiratoire en temps réel","Mémorisation des séances","PIM mesurée par un manomètre intégré"],"r":[0,1,2,3],"e":"Les quatre fonctionnalités sont citées.","s":7},{"q":"Quelle est la fréquence d'entraînement recommandée chez le patient ?","o":["1 à 2 fois par jour, 3 à 7 jours par semaine","1 à 2 fois par jour, 5 à 7 jours par semaine, comme chez le sujet sain","1 fois par jour, 1 jour par semaine","3 fois par jour, 7 jours par semaine"],"r":0,"e":"Patients : 1-2×/jour, 3-7 j/semaine. Sujets sains : 1-2×/jour, 5-7 j/semaine.","s":7},{"q":"Après combien de temps les adaptations sont-elles évidentes chez l'individu en bonne santé ?","o":["Après 3 à 4 semaines","Après 6 semaines","Après 2 semaines","Après 3 mois"],"r":0,"e":"Sujets sains : adaptations évidentes après 3-4 semaines. Patients : après 6 semaines.","s":7},{"q":"Quelle est l'étape 2 du protocole de Vergara (2004) ?","o":["Réévaluer la PIM du patient","Entraîner à 30 % des nouvelles PIM","Ajouter un travail de renforcement","Entraîner les expiratoires à 25 %"],"r":0,"e":"Étape 0 : évaluer la PIM. 1 : 7-10 jours à 25 % de la PIM. 2 : réévaluer la PIM. 3 : entraîner à 30 % des nouvelles PIM. 4 : ajouter le renforcement.","s":7},{"q":"En quoi consiste l'entraînement de renforcement ajouté au protocole de Vergara ?","o":["Tous les 7 ou 8 cycles, une inspiration à 60 ou 70 % de la PIM","Tous les jours, une séance entière à 100 % de la PIM","Toutes les semaines, une séance de durée doublée","Tous les 7 ou 8 cycles, une expiration à 60 ou 70 % de la PEM"],"r":0,"e":"À partir de l'étape 2, on ajoute tous les 7 ou 8 cycles une inspiration à 60 ou 70 % de la PIM.","s":7},{"q":"Comment entraîne-t-on les muscles expiratoires selon Vergara ?","o":["De la même façon, à différents pourcentages de la PEM","Avec des charges abdominales seulement","Ils ne sont jamais entraînés dans ce protocole","Avec le Threshold IMT, à 25 % de la PIM, sans aucune progression"],"r":0,"e":"Le protocole est identique pour les muscles expiratoires, en travaillant des expirations à différents pourcentages de la PEM.","s":7},{"q":"Quels sont les trois effets possibles du positionnement sur le transport d'oxygène ?","o":["Il peut être amélioré, maintenu ou aggravé","Il est toujours amélioré, quelle que soit la position","Il est toujours maintenu, quelle que soit la position","Il n'est jamais modifié par la position"],"r":0,"e":"Chaque position reflète les effets de la pesanteur, à laquelle le corps est continuellement exposé.","s":8},{"q":"Quelle est la position la plus physiologique ?","o":["La position debout","Le décubitus dorsal","Le décubitus latéral","Le décubitus ventral"],"r":0,"e":"Associée au mouvement (marche, cycloergométrie), elle optimise le transport d'oxygène jusqu'à sa valeur maximale.","s":8},{"q":"Quel effet la position debout a-t-elle sur les voies aériennes ?","o":["Le diamètre des grosses voies aériennes augmente un peu","Le diamètre des grosses voies aériennes diminue nettement, surtout aux bases","Le diamètre des grosses voies aériennes ne change pas","Les voies aériennes distales se collabent"],"r":0,"e":"La position debout maximise aussi les volumes et capacités pulmonaires.","s":8},{"q":"En position debout, quels champs pulmonaires sont mieux ventilés ?","o":["Les champs non dépendants : les sommets","Les champs dépendants : les bases","Les deux de façon identique","Le poumon droit uniquement"],"r":0,"e":"Ce sont les champs dépendants (les bases) qui sont mieux perfusés.","s":8},{"q":"En position debout, quels champs pulmonaires sont mieux perfusés ?","o":["Les champs dépendants : les bases","Les champs non dépendants : les sommets","Les deux de façon identique","Le poumon gauche uniquement"],"r":0,"e":"À l'inverse, les sommets sont mieux ventilés.","s":8},{"q":"Pourquoi le décubitus dorsal est-il considéré comme non physiologique ?","o":["Il modifie le thorax, les coupoles et la pression abdominale","Il augmente la CRF, le volume courant et la compliance","Il améliore l'oxygénation, la perfusion et la ventilation","Il facilite le drainage, la toux et la clairance"],"r":0,"e":"Il n'est physiologique que pendant le sommeil.","s":8},{"q":"Dans quel sens se déplacent les hémidiaphragmes en décubitus dorsal ?","o":["Vers le haut (céphalad)","Vers le bas (caudal)","Vers l'avant","Ils ne se déplacent pas"],"r":0,"e":"Ce déplacement s'accompagne d'une réduction de la CRF.","s":8},{"q":"Quelle conséquence a l'accumulation de sécrétions dans les régions dépendantes en décubitus dorsal ?","o":["Un risque accru d'obstruction et d'infection","Une amélioration de la compliance pulmonaire","Une hausse du volume courant dans les bases","Une meilleure oxygénation des zones dépendantes"],"r":0,"e":"C'est l'une des raisons pour lesquelles cette position est à surveiller.","s":8},{"q":"Pourquoi l'hémidiaphragme dépendant a-t-il une plus grande excursion en décubitus latéral ?","o":["Les viscères le repoussent vers le haut","Le médiastin le comprime vers le bas","La perfusion y est moindre qu'en haut","La paroi thoracique y est bloquée par l'appui"],"r":0,"e":"Le décubitus latéral est plus physiologique que le décubitus dorsal.","s":8},{"q":"Quels sont les effets du décubitus ventral ?","o":["Oxygénation, volume courant et compliance accrus","Compliance, volume courant et oxygénation diminués","Oxygénation réduite, travail respiratoire accru","Volume courant réduit, compliance inchangée"],"r":0,"e":"Il réduit le travail respiratoire chez les patients avec dysfonction cardiopulmonaire. Le travail respiratoire est réduit.","s":8},{"q":"Quel mouvement du tronc s'associe à l'inspiration ?","o":["L'extension du tronc","La flexion du tronc","La rotation du tronc","L'inclinaison latérale"],"r":0,"e":"La flexion du tronc s'associe à l'expiration.","s":8},{"q":"Quels mouvements de l'épaule s'associent à l'inspiration ?","o":["Flexion, abduction et rotation externe","Extension, adduction et rotation interne","Adduction et rotation externe","Extension et abduction"],"r":0,"e":"Les mouvements inverses accompagnent l'expiration.","s":8},{"q":"Quel mouvement cervical s'associe à l'expiration ?","o":["La flexion cervicale (regarder vers le bas)","L'extension cervicale (regarder vers le haut)","La rotation cervicale","L'inclinaison cervicale"],"r":0,"e":"L'extension cervicale accompagne l'inspiration.","s":8},{"q":"Quel effet a la consigne de lever la tête et regarder ses mains pendant l'extension des épaules ?","o":["Elle renforce la contraction abdominale et intercostale à l'expiration","Elle facilite l'inspiration profonde","Elle diminue le travail respiratoire","Elle bloque le diaphragme en position haute pendant toute l'expiration"],"r":0,"e":"C'est un exemple de stratégie de ventilation-mouvement à l'expiration.","s":8},{"q":"Que favorise la flexion de la hanche et des genoux pendant l'expiration ?","o":["Une bascule postérieure et une flexion du tronc","Une bascule antérieure et une extension du tronc","Une ouverture costale supérieure en inspiration","Une inspiration profonde à haut volume pulmonaire"],"r":0,"e":"C'est une stratégie de ventilation-mouvement expiratoire.","s":8},{"q":"Que permet la mobilisation manuelle thoracique sur la grille costale ?","o":["Son expansion, par des diamètres antéro-postérieur et transverse accrus","Sa fermeture, par des diamètres antéro-postérieur et transverse réduits","Son allongement, par un seul diamètre vertical accru","Son blocage, par la fixation des segments hypermobiles"],"r":0,"e":"Il s'ensuit une diminution de l'espace mort et du volume résiduel.","s":8},{"q":"Quelle conséquence physiologique la MMT a-t-elle sur l'espace mort ?","o":["Elle le diminue, et le volume résiduel aussi","Elle l'augmente, et le volume résiduel aussi","Elle ne le modifie pas","Elle augmente le volume résiduel seul"],"r":0,"e":"L'augmentation du volume courant améliore l'oxygénation sanguine.","s":8},{"q":"Quelle MMT facilite l'excursion diaphragmatique ?","o":["La MMT costale inférieure","La MMT costale supérieure","La MMT costale moyenne","La MMT sternale"],"r":0,"e":"La MMT costale moyenne recrute principalement les intercostaux externes.","s":8},{"q":"Quels muscles la MMT costale moyenne recrute-t-elle principalement ?","o":["Les intercostaux externes","Le diaphragme, en partie costale","Les scalènes","Les abdominaux"],"r":0,"e":"La MMT costale inférieure facilite plutôt l'excursion diaphragmatique.","s":8},{"q":"Quel matériel simple facilite l'ouverture costale ?","o":["Des coussins ou des rouleaux","Un spiromètre incitatif","Un masque à oxygène","Un peak flow meter"],"r":0,"e":"On utilise aussi les stratégies de ventilation-mouvement, la thérapie manuelle, les étirements et les techniques myofasciales.","s":8},{"q":"À quoi servent les techniques myofasciales en mobilisation thoracique ?","o":["À libérer le tissu conjonctif","À renforcer le diaphragme","À drainer les sécrétions distales","À mesurer les périmètres thoraciques"],"r":0,"e":"La thérapie manuelle sert quant à elle à débloquer des segments spécifiques.","s":8},{"q":"La MMT peut-elle être réalisée d'un seul côté ?","o":["Oui, bilatérale ou unilatérale","Non, seulement bilatérale","Non, seulement du côté atteint","Seulement chez l'enfant"],"r":0,"e":"Le choix dépend de la région à traiter.","s":8},{"q":"Cas 1 : parésie diaphragmatique après cholécystectomie — quel est l'objectif ?","o":["Mobiliser le diaphragme et la base droite contre l'hypoventilation","Améliorer le rapport ventilation-perfusion et l'oxygénation","Augmenter la mobilité costale gauche à tous les niveaux","Faciliter la réabsorption du liquide pleural à droite"],"r":0,"e":"Il s'agit d'un homme de 56 ans opéré d'une cholécystectomie.","s":8},{"q":"Cas 2 : atélectasie droite avec SpO₂ à 82 % — quel est l'objectif ?","o":["Améliorer le rapport ventilation-perfusion et l'oxygénation","Augmenter la mobilité costale gauche à tous les niveaux","Réduire la douleur costale à droite pour mieux respirer","Faciliter la réabsorption du liquide pleural à droite"],"r":0,"e":"Il s'agit d'un homme de 72 ans.","s":8},{"q":"Cas 3 : fractures de côtes gauches après une chute de 3 mètres — quel est l'objectif ?","o":["Mobiliser tout l'hémithorax gauche et la coupole gauche","Augmenter la mobilité costale droite à tous les niveaux","Améliorer seulement l'oxygénation par le positionnement","Réabsorber un épanchement pleural de la base gauche"],"r":0,"e":"L'objectif est d'améliorer l'hypoventilation gauche.","s":8},{"q":"Cas 4 : épanchement pleural gauche secondaire à une pneumonie — quel est l'objectif ?","o":["Mobiliser la base et la coupole droites, aider à réabsorber le liquide","Mobiliser seulement l'hémithorax gauche, sans toucher au diaphragme","Réduire le volume courant pour limiter la douleur pleurale gauche","Diminuer la compliance gauche pour éviter une récidive de l'épanchement"],"r":0,"e":"Il s'agit d'un homme de 56 ans. L'objectif est de réduire l'hypoventilation basale droite.","s":8},{"q":"Quelle association est correcte pour l'inspiration ?","o":["Extension du tronc et du cou, flexion-abduction-RE d'épaule","Flexion du tronc et du cou, extension-adduction-RI d'épaule","Extension du tronc, flexion du cou, adduction-RI d'épaule","Flexion du tronc, extension du cou, flexion-abduction-RE d'épaule, bras au-dessus de la tête"],"r":0,"e":"Les mouvements inverses sont associés à l'expiration. RE et RI : rotation externe et rotation interne.","s":8},{"q":"Quelle est la conséquence de la remontée des viscères en décubitus dorsal ?","o":["Une augmentation de la pression abdominale","Une baisse de la pression abdominale","Une augmentation de la CRF","Un abaissement des coupoles"],"r":0,"e":"Elle contribue au déplacement céphalad des hémidiaphragmes et à la réduction de la CRF.","s":8},{"q":"Quelle position est décrite comme plus physiologique que le décubitus dorsal ?","o":["Le décubitus latéral","Le décubitus ventral strict","La position de Trendelenburg","La position assise inclinée en arrière"],"r":0,"e":"L'hémidiaphragme dépendant y bénéficie d'une plus grande excursion.","s":8},{"q":"Quel est l'effet global recherché par la MMT sur l'oxygénation ?","o":["Une meilleure oxygénation, par un volume courant accru","Une ventilation diminuée, pour économiser de l'énergie","Un espace mort augmenté, par une ventilation plus ample","Un volume résiduel augmenté, par des alvéoles mieux ouvertes"],"r":0,"e":"Elle s'accompagne d'une diminution de l'espace mort et du volume résiduel.","s":8},{"q":"Pourquoi la position debout optimise-t-elle le transport d'oxygène ?","o":["Elle maximise les volumes et capacités pulmonaires","Les grosses voies aériennes s'élargissent un peu","Associée au mouvement, elle donne le transport maximal","Elle supprime totalement l'effet de la pesanteur sur le poumon"],"r":[0,1,2],"e":"La position debout est la plus physiologique : volumes et capacités maximisés, diamètre des voies aériennes légèrement augmenté, et transport optimal lorsqu'elle est associée au mouvement.","s":8},{"q":"Que modifie le décubitus dorsal ?","o":["La configuration de la cage thoracique","La position des hémidiaphragmes","La pression abdominale","Le diamètre de la trachée cervicale"],"r":[0,1,2],"e":"Ces trois modifications expliquent la réduction de la CRF et l'accumulation de sécrétions dans les régions dépendantes. La pression abdominale augmente par la remontée des viscères ; les hémidiaphragmes se déplacent dans le sens antéro-postérieur.","s":8},{"q":"Quels risques découlent de l'accumulation de sécrétions en décubitus dorsal ?","o":["Un risque accru d'obstruction","Un risque accru d'infection","Une augmentation de la CRF","Une meilleure ventilation des bases"],"r":[0,1],"e":"L'accumulation dans les régions dépendantes majore les risques d'obstruction et d'infection, la CRF étant au contraire réduite.","s":8},{"q":"Chez quels patients le décubitus ventral produit-il ses effets bénéfiques ?","o":["Chez les patients avec dysfonction cardiopulmonaire","Chez les patients neurologiques uniquement","Chez les sujets sains uniquement","Chez les patients en post-opératoire abdominal"],"r":0,"e":"Le décubitus ventral augmente l'oxygénation artérielle, le volume courant et la compliance et réduit le travail respiratoire chez les patients avec dysfonction cardiopulmonaire.","s":8},{"q":"Quels mouvements composent le schéma expiratoire en ventilation-mouvement ?","o":["Flexion du tronc","Extension-adduction-RI d'épaule","Flexion cervicale","Extension cervicale"],"r":[0,1,2],"e":"Le schéma expiratoire associe flexion du tronc, extension/adduction/rotation interne d'épaule et flexion cervicale. L'extension cervicale appartient au schéma inspiratoire. RI : rotation interne.","s":8},{"q":"Quelle consigne accompagne l'inspiration en ventilation-mouvement ?","o":["Regarder vers le haut en élevant les bras et les épaules","Lever la tête et regarder ses mains pendant l'extension","Fléchir la hanche et les genoux pendant le mouvement","Regarder vers le bas en enroulant les épaules et le tronc"],"r":0,"e":"Pour l'inspiration : regarder vers le haut en élevant bras et épaules. Les deux autres consignes favorisent l'expiration.","s":8},{"q":"Quels sont les effets de la mobilisation manuelle thoracique ?","o":["Grille costale élargie, diamètres antéro-postérieur et transverse","Espace mort et volume résiduel diminués","Volume courant et ventilation pulmonaire accrus","Compliance pulmonaire et thoracique diminuée"],"r":[0,1,2],"e":"Ces trois effets aboutissent à une meilleure oxygénation sanguine.","s":8},{"q":"Quelles techniques de mobilisation thoracique sont décrites ?","o":["Coussins ou rouleaux pour ouvrir le gril costal","Stratégies de ventilation-mouvement","Thérapie manuelle des segments bloqués","Étirements et techniques myofasciales","Percussion thoracique rythmée au poing"],"r":[0,1,2,3],"e":"Cinq familles de techniques sont décrites.","s":8},{"q":"Cas 2 : homme de 72 ans avec atélectasie droite et SpO₂ à 82 %. Quel est l'objectif ?","o":["Améliorer le rapport ventilation-perfusion et l'oxygénation","Augmenter la mobilité costale gauche à tous les niveaux et la mobilité de la coupole","Faciliter la réabsorption du liquide pleural","Traiter une parésie diaphragmatique"],"r":0,"e":"Le cas 2 vise l'amélioration du rapport ventilation-perfusion, donc des échanges gazeux et de l'oxygénation.","s":8},{"q":"Cas 4 : épanchement pleural gauche secondaire à une pneumonie. Quels sont les objectifs ?","o":["Augmenter la mobilité costale inférieure droite et diaphragmatique droite","Réduire l'hypoventilation basale droite","Faciliter la réabsorption du liquide pleural","Augmenter la mobilité costale gauche à tous les niveaux"],"r":[0,1,2],"e":"Le cas 4 combine ces trois objectifs. L'augmentation de la mobilité costale gauche à tous les niveaux concerne le cas 3, celui des fractures de côtes.","s":8},{"q":"Pourquoi le décubitus dorsal est-il malgré tout physiologique dans une situation précise ?","o":["Pendant le sommeil","Pendant l'effort","Pendant les repas","Il ne l'est jamais"],"r":0,"e":"La fiche précise que le décubitus dorsal est une position non physiologique, sauf pendant le sommeil.","s":8},{"q":"Qu'est-ce qui explique la plus grande excursion de l'hémidiaphragme dépendant en décubitus latéral ?","o":["Les viscères le repoussent vers le haut","Le poids du thorax le comprime vers le bas","Il est mieux perfusé que celui du dessus","Il perd son tonus sous l'effet de l'appui"],"r":0,"e":"En décubitus latéral, la pression des viscères déplace l'hémidiaphragme dépendant vers le haut, ce qui lui donne une plus grande excursion respiratoire.","s":8},{"q":"Pourquoi ventilation et perfusion ne se distribuent-elles pas de la même façon en position debout ?","o":["Le haut est mieux ventilé, le bas est mieux perfusé","Le bas est mieux ventilé et mieux perfusé, car la gravité attire l'air et le sang","Le haut est mieux ventilé et mieux perfusé","Les deux se répartissent de façon homogène"],"r":0,"e":"Debout : les sommets sont mieux ventilés que les bases, mais les bases sont mieux perfusées que les sommets.","s":8},{"q":"Quel est l'effet de la consigne « lever la tête et regarder ses mains pendant l'extension des épaules » ?","o":["Elle augmente la contraction abdominale et intercostale","Elle facilite l'inspiration profonde et l'ouverture costale","Elle relâche le diaphragme en fin d'inspiration","Elle ouvre la grille costale supérieure en inspiration"],"r":0,"e":"Cette consigne expiratoire augmente la contraction abdominale et intercostale.","s":8},{"q":"Que favorise la flexion de hanche et de genoux pendant l'expiration ?","o":["Une bascule postérieure du bassin","Une flexion du tronc","Une extension cervicale","Une abduction d'épaule"],"r":[0,1],"e":"Fléchir hanche et genoux pendant l'expiration favorise une bascule postérieure du bassin et une flexion du tronc — deux composantes du schéma expiratoire.","s":8},{"q":"Cas 3 : chute de 3 mètres avec fractures de côtes à gauche. Quel est l'objectif ?","o":["Mobiliser tout l'hémithorax gauche et la coupole gauche","Traiter une atélectasie droite par le positionnement","Réabsorber un épanchement pleural de la base gauche","Corriger une parésie diaphragmatique droite"],"r":0,"e":"Le cas 3 vise la mobilité costale gauche à tous les niveaux et la mobilité diaphragmatique gauche.","s":8},{"q":"À quoi servent les techniques myofasciales dans la mobilisation thoracique ?","o":["À libérer le tissu conjonctif","À renforcer les intercostaux","À drainer les sécrétions","À mesurer les amplitudes"],"r":0,"e":"Les techniques myofasciales libèrent le tissu conjonctif, parmi les cinq familles de techniques de mobilisation thoracique.","s":8},{"q":"Comment la position corporelle agit-elle sur le transport d'oxygène ?","o":["Selon la position, la pesanteur l'améliore, le maintient ou l'aggrave","Elle n'a aucun effet, la pesanteur étant compensée par le cœur","Elle l'améliore toujours, quelle que soit la position choisie","Elle ne joue que chez le patient ventilé, sous sédation"],"r":0,"e":"Le corps est continuellement exposé à la pesanteur : selon la position, le transport d'oxygène est amélioré, maintenu ou aggravé.","s":8},{"q":"Quelle conséquence a la remontée des viscères en décubitus dorsal ?","o":["Une pression abdominale accrue, des coupoles repoussées vers le haut","Une pression abdominale réduite, des coupoles abaissées vers le bas","Une CRF augmentée, des bases mieux ouvertes","Une meilleure ventilation des bases, des coupoles plus mobiles"],"r":0,"e":"La remontée des viscères augmente la pression abdominale et déplace les hémidiaphragmes vers le haut, ce qui réduit la CRF.","s":8},{"q":"Quel est l'effet global recherché par la mobilisation manuelle thoracique sur l'oxygénation ?","o":["Une meilleure oxygénation, par un volume courant accru","Une baisse de la fréquence respiratoire et cardiaque","Une augmentation du volume résiduel et de l'espace mort","Une diminution de la compliance, par un thorax plus rigide"],"r":0,"e":"En augmentant le volume courant et la ventilation pulmonaire, et en diminuant l'espace mort et le volume résiduel, la MMT améliore l'oxygénation sanguine.","s":8}]};
